// # LESSON DATA — Part 17: Reading Lessons B1 + B2 (50 lessons: B1=25, B2=25)
// # ═══════════════════════════════════════════════════════════════════════════

import type { LessonCategory } from './types'

export const LESSON_CATEGORIES_17: LessonCategory[] = [
  {
    id: 'b1-reading',
    name: 'B1: Reading Skills',
    description: 'Read and understand longer texts — articles, stories, reports, and opinion pieces on familiar topics.',
    icon: '📖',
    lessons: [
      // # ─── Lesson 1: Reading Longer Articles ───
      { id: 'b1-reading-longer-articles', title: 'Reading Longer Articles', description: 'Build stamina for texts of 300-500 words — the length of a typical online article.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Read a full article without losing focus', 'Identify the thesis (main argument) and supporting points', 'Summarise a 400-word article in 2-3 sentences'],
        sections: [
          { title: 'Article Anatomy', type: 'rule', content: 'A well-structured article has: HEADLINE: grabs attention, often uses a question or strong claim. HOOK (first 1-2 sentences): pulls you in with a surprising fact, question, or story. THESIS: the main argument or point — usually at the end of the first paragraph. BODY PARAGRAPHS: each one makes ONE supporting point with evidence. CONCLUSION: restates the thesis, often with a call to action or question. Key skill at B1: find the thesis. Ask: "What is the writer\'s main point?" Everything else supports it.' },
          { title: 'Paragraph-Level Reading', type: 'tip', content: 'At B1, start reading at the PARAGRAPH level, not just sentence by sentence. Each paragraph has: a topic sentence (usually first) — the main idea of THAT paragraph. Supporting sentences — examples, data, explanations. A linking sentence (sometimes) — connects to the next paragraph. After reading each paragraph, pause and ask: "What was the point of that paragraph?" If you can answer in one sentence, you understood it. If you can\'t, re-read it. This "paragraph pause" technique dramatically improves comprehension of longer texts.' },
          { title: 'Find the Thesis', type: 'exercise', question: '"Remote work is here to stay. A recent survey found that 78% of companies plan to allow permanent remote options. Employees report higher satisfaction, with 65% saying they are more productive at home. Critics argue that remote work damages team culture, but companies like GitLab and Automattic have thrived as fully remote organisations for over a decade. The evidence is clear: flexibility, not location, determines workplace success." What is the thesis?', answer: 'Thesis: "Flexibility, not location, determines workplace success." Everything else supports this claim — the survey data (78% of companies), employee satisfaction (65%), and the counter-argument with rebuttal (critics say team culture suffers, but GitLab/Automattic prove otherwise).', answerExplanation: 'The thesis is the last sentence — a common position in articles that build their case before stating the conclusion. The supporting evidence progresses: general data → employee feelings → counter-argument dismissed → thesis. Recognising this structure makes any article easier to follow.' },
        ],
        keyTakeaways: ['The thesis is the main argument — usually in the first or last paragraph', 'Each paragraph makes ONE point — pause after each to check you understood', 'After reading, you should be able to summarise the whole article in 2-3 sentences'],
      },
      // # ─── Lesson 2: Identifying Tone ───
      { id: 'b1-reading-tone', title: 'Identifying Tone — How the Writer Feels', description: 'Detect whether a text is serious, humorous, critical, or enthusiastic.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Identify the writer\'s tone from word choice', 'Distinguish between neutral, positive, and negative tones', 'Recognise sarcasm and irony in simple texts'],
        sections: [
          { title: 'Common Tones', type: 'rule', content: 'NEUTRAL / OBJECTIVE: no opinion — uses facts, data, formal language. "The population increased by 3%." POSITIVE / ENTHUSIASTIC: the writer is excited or approving. "This brilliant new app transforms how we learn." NEGATIVE / CRITICAL: the writer disapproves. "This poorly designed policy will hurt millions." HUMOROUS: uses jokes, exaggeration, or wordplay. "I\'ve eaten so much I might actually explode." SARCASTIC: says the OPPOSITE of what they mean. "Oh great, another Monday. My favourite." FORMAL: professional, no contractions. INFORMAL: casual, contractions, slang.' },
          { title: 'Tone Clues', type: 'tip', content: 'Word choice reveals tone: Positive: brilliant, excellent, innovative, inspiring, remarkable. Negative: disastrous, appalling, absurd, pointless, reckless. Neutral: adequate, standard, average, moderate. Exaggeration signals humour or sarcasm: "the worst day in human history" (about losing a sock). Rhetorical questions often signal criticism: "How could anyone think this was a good idea?" Exclamation marks can signal enthusiasm ("Amazing!") or sarcasm ("What a surprise!"). Context determines which — read the surrounding sentences.' },
          { title: 'Name the Tone', type: 'exercise', question: '(a) "The new law will provide essential protections for vulnerable workers." (b) "Ah yes, because clearly what we needed was MORE paperwork." (c) "The temperature rose by 1.2°C between 2020 and 2025."', answer: '(a) Positive / supportive — "essential protections" and "vulnerable workers" show approval. (b) Sarcastic — "Ah yes" and "clearly" with "MORE paperwork" shows the writer thinks it is unnecessary. They mean the opposite of what they say. (c) Neutral / objective — no opinion words, just a fact with a number.', answerExplanation: '"Essential" and "vulnerable" carry positive/sympathetic weight. "Ah yes, because clearly" is a sarcasm formula — the words say agreement but the meaning is mockery. Pure numbers with no adjectives = neutral. Identifying tone prevents misunderstanding the writer\'s intention.' },
        ],
        keyTakeaways: ['Word choice reveals tone — "brilliant" (positive), "disastrous" (negative), "average" (neutral)', 'Sarcasm says the OPPOSITE of what it means — look for "Ah yes", "clearly", "of course"', 'Neutral texts use facts and numbers without adjective judgements'],
      },
      // # ─── Lesson 3: Understanding Paragraph Structure ───
      { id: 'b1-reading-paragraph-structure', title: 'Understanding Paragraph Structure', description: 'See how paragraphs are built — topic sentence, support, and transition.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Identify topic sentences', 'Recognise supporting details (examples, statistics, explanations)', 'Understand how paragraphs link to each other'],
        sections: [
          { title: 'Paragraph Building Blocks', type: 'rule', content: 'Topic sentence: states the paragraph\'s main idea. Usually the FIRST sentence. "Exercise has many benefits for mental health." Supporting sentences: give evidence, examples, data. "A 2024 study found that 30 minutes of walking reduces anxiety by 25%." "For example, jogging releases endorphins, which improve mood." Concluding/transition sentence: wraps up or links to the next paragraph. "Given these benefits, it is surprising that so few people exercise regularly." — this transitions to a paragraph about barriers to exercise.' },
          { title: 'When the Topic Sentence Isn\'t First', type: 'tip', content: 'Sometimes the topic sentence is: LAST (after building evidence): "Stress levels drop. Sleep improves. Mood lifts. Clearly, exercise is essential for mental health." → the topic sentence is the conclusion. IN THE MIDDLE: "Many people struggle with anxiety. However, regular exercise can significantly reduce symptoms. Studies show..." → the main idea is the second sentence. IMPLICIT (not stated): the paragraph gives examples and you must infer the point. This is rare at B1 but common at C1-C2. Rule of thumb: if the first sentence isn\'t the main idea, check the last sentence. If neither works, look for the sentence that all other sentences support.' },
          { title: 'Find the Topic Sentence', type: 'exercise', question: '"Social media has changed how we communicate. Teenagers spend an average of 3 hours per day on social platforms. Many adults use social media for news rather than traditional newspapers. Businesses now spend 40% of their marketing budget on social media advertising. Even governments use platforms like X to communicate with citizens." Which sentence is the topic sentence?', answer: 'The first sentence: "Social media has changed how we communicate." Every other sentence is a SUPPORTING DETAIL showing HOW it changed communication — teenagers (personal), adults (news), businesses (marketing), governments (official). All four examples support the claim that social media changed communication.', answerExplanation: 'The topic sentence makes a broad claim. The supporting sentences provide specific evidence. If you removed the first sentence, the examples would be a random list. The topic sentence gives them meaning and direction.' },
        ],
        keyTakeaways: ['The topic sentence is usually first — it states the paragraph\'s main point', 'Supporting sentences provide evidence: examples, statistics, explanations', 'If the first sentence isn\'t the topic, check the last sentence'],
      },
      // # ─── Lesson 4: Reading Opinion Articles ───
      { id: 'b1-reading-opinion-articles', title: 'Reading Opinion Articles & Editorials', description: 'Evaluate texts where the writer argues for a position on a controversial topic.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Identify the writer\'s position (for or against)', 'Spot persuasive techniques', 'Evaluate whether the argument is convincing'],
        sections: [
          { title: 'Opinion Article Structure', type: 'rule', content: 'Opening: states the issue and the writer\'s position. "School uniforms should be abolished." Arguments FOR the position: 2-3 paragraphs, each with one argument + evidence. Counter-argument: acknowledges the other side. "Some argue that uniforms reduce bullying, but..." Rebuttal: explains why the counter-argument is weak. "...however, research shows bullying is about behaviour, not clothing." Conclusion: restates the position strongly. Look for: "should," "must," "need to" — these signal opinion, not fact.' },
          { title: 'Persuasive Techniques', type: 'tip', content: 'Writers persuade you using: EMOTIONAL APPEAL: "Think of the children who suffer..." STATISTICS: "73% of experts agree..." EXPERT OPINION: "According to Professor Smith..." ANECDOTES: "When I was 12, I experienced..." RHETORICAL QUESTIONS: "Can we really afford to ignore this?" REPETITION: "We need change. We need action. We need it now." INCLUSIVE LANGUAGE: "We all know..." "As a society, we must..." None of these make an argument TRUE — they make it PERSUASIVE. A strong argument uses evidence, not just emotion.' },
          { title: 'Evaluate This Argument', type: 'exercise', question: '"Plastic bags should be banned completely. Every year, 8 million tonnes of plastic end up in our oceans, killing marine life and contaminating our food chain. Think about the turtles choking on plastic bags — is your convenience really worth their lives? Some argue that plastic bags are necessary for hygiene, but reusable bags are just as clean when washed regularly." Is this convincing? What techniques does it use?', answer: 'Techniques: (1) Statistics — "8 million tonnes" (appeals to logic). (2) Emotional appeal — "turtles choking" (appeals to sympathy). (3) Rhetorical question — "is your convenience really worth their lives?" (makes you feel guilty). (4) Counter-argument + rebuttal — hygiene concern dismissed with a practical solution. Fairly convincing because it combines emotion WITH evidence, and addresses the other side. Weakness: only one counter-argument is addressed — what about cost, durability, or convenience for disabled people?', answerExplanation: 'Strong opinion articles use BOTH evidence and emotion, and address counter-arguments. Weak ones rely on emotion alone. Evaluating arguments means asking: "Is the evidence real? Are all sides considered? Am I being manipulated or informed?" This is critical thinking.' },
        ],
        keyTakeaways: ['"Should", "must", "need to" signal the writer\'s opinion, not fact', 'Persuasive techniques: statistics, emotions, rhetorical questions, expert quotes', 'A strong argument addresses counter-arguments — a weak one ignores them'],
      },
      // # ─── Lesson 5: Reading Narrative Non-Fiction ───
      { id: 'b1-reading-narrative-nonfiction', title: 'Reading Narrative Non-Fiction', description: 'Understand true stories told in a narrative style — journalism, memoirs, and case studies.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Follow a chronological narrative with flashbacks', 'Distinguish between the narrator\'s experience and general facts', 'Identify the theme or message of a true story'],
        sections: [
          { title: 'What Is Narrative Non-Fiction?', type: 'rule', content: 'Narrative non-fiction = TRUE stories told like fiction. Uses: vivid description, dialogue, scene-setting, character development. But everything is REAL — actual events, real people, verified facts. Common types: long-form journalism ("The story of the man who survived 76 days at sea"). Memoirs ("When I first arrived in London with £50 in my pocket..."). Case studies ("How one school transformed its exam results in 3 years"). The writer builds a scene: "It was 3 AM when the phone rang. Maria stared at the screen, knowing this call would change everything." — this is storytelling, not fiction.' },
          { title: 'Following Time in Narratives', type: 'tip', content: 'Narratives don\'t always follow time order. Watch for: FLASHBACK: "Three years earlier, she had been..." (jumps to the past). FLASH-FORWARD: "She didn\'t know it yet, but this decision would..." (hints at the future). TIME MARKERS: "Meanwhile," "At the same time," "Back in London," "By 2020," "Looking back now..." SCENE BREAKS: a gap or *** between paragraphs = time or location change. When you lose track of time in a narrative, look for the last time marker and work forward from there.' },
          { title: 'Read This Extract', type: 'exercise', question: '"The morning of the interview, James woke up at 5 AM. He had barely slept. Six months earlier, he had been living on the streets — no address, no phone, no hope. A charity worker named Helen had noticed him outside a library and offered him a place in a job training programme. Now, standing in a borrowed suit, he felt like a different person. He didn\'t get the job. But three weeks later, another offer came."', answer: 'Timeline: (1) Six months ago — James was homeless. (2) Helen offered him a training programme. (3) Morning of the interview — barely slept, wearing a borrowed suit. (4) Interview — he didn\'t get the job. (5) Three weeks later — another job offer came. Theme: Perseverance and second chances. The flashback ("Six months earlier") gives context — without it, the scene of a nervous man in a suit has no emotional weight.', answerExplanation: 'The narrative starts in the present (interview morning), jumps back (six months earlier), returns to the present, then moves forward (three weeks later). This structure creates suspense and empathy. The borrowed suit detail tells you he\'s not yet financially stable — narrative non-fiction uses small details to show, not tell.' },
        ],
        keyTakeaways: ['Narrative non-fiction = true stories told like fiction — vivid, emotional, but real', 'Watch for time jumps: "Three years earlier", "Meanwhile", "Looking back now"', 'Small details (borrowed suit, £50 in pocket) carry meaning — they show the person\'s situation'],
      },
      // # ─── Lesson 6: Inference — Reading Between the Lines ───
      { id: 'b1-reading-inference', title: 'Inference — Reading Between the Lines', description: 'Understand what a text IMPLIES without saying it directly.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Infer meanings from context and word choice', 'Understand what is implied but not stated', 'Distinguish between what is stated, implied, and not given'],
        sections: [
          { title: 'What Is Inference?', type: 'rule', content: 'Inference = understanding something the text does NOT say directly but SUGGESTS through clues. Text: "She grabbed her umbrella and raincoat before leaving." Inference: It is raining (or about to rain). The text doesn\'t SAY "it was raining" — but the umbrella and raincoat are clues. Inference uses: context clues (the situation), word choice (emotional language), what is NOT said (important absences), general knowledge (how the world works). At B1, you move beyond "what does it say?" to "what does it MEAN?"' },
          { title: 'Types of Inference', type: 'tip', content: 'CHARACTER INFERENCE: "He slammed the door and didn\'t speak to anyone for hours." → He is angry/upset. SETTING INFERENCE: "The leaves were orange and the air was crisp." → It is autumn. ATTITUDE INFERENCE: "The politician claimed the project was \'on track.\'" → The quotation marks around "on track" suggest the writer doubts it. OUTCOME INFERENCE: "She studied every night for three months." → She probably passed the exam (but the text doesn\'t say so). Be careful: inference should be SUPPORTED by the text, not just your opinion. "She grabbed an umbrella" → raining (supported). "She grabbed an umbrella" → she is a careful person (possible but weak).' },
          { title: 'What Can You Infer?', type: 'exercise', question: '"The restaurant had been open for just six months. The paint on the walls was already peeling. Three waiters had quit in the last month alone, and reviews online were mostly one-star. The owner sat at a corner table, staring at a stack of unpaid bills." What can you infer about the restaurant\'s future?', answer: 'The restaurant is likely going to close. Evidence: (1) Peeling paint = poor maintenance / no money for repairs. (2) Three waiters quit = staff are unhappy, probably not being paid well. (3) One-star reviews = customers are not satisfied. (4) Unpaid bills = financial problems. (5) Owner "staring" at bills = overwhelmed, possibly giving up. None of this says "the restaurant will close" — but every detail points to failure.', answerExplanation: 'Strong inference combines multiple clues. One peeling wall might mean nothing. But peeling walls + staff quitting + bad reviews + unpaid bills + a dejected owner = a clear pattern. This is how inference works in real reading — no single clue is definitive, but together they paint a picture.' },
        ],
        keyTakeaways: ['Inference = understanding what the text SUGGESTS, not just what it SAYS', 'Use multiple clues together — one detail is weak, three is strong', 'Good inference is SUPPORTED by the text, not just your personal guess'],
      },
      // # ─── Lesson 7: Reading Cause & Effect Texts ───
      { id: 'b1-reading-cause-effect', title: 'Reading Cause & Effect Texts', description: 'Follow chains of causes and effects in explanatory and scientific texts.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Identify cause and effect relationships', 'Understand signal words: because, therefore, as a result, leads to', 'Follow multi-step cause-effect chains'],
        sections: [
          { title: 'Cause & Effect Language', type: 'rule', content: 'CAUSE → EFFECT connectors: "because" / "since" / "as": "Sales dropped because prices were too high." "due to" / "owing to": "The delay was due to bad weather." "therefore" / "as a result" / "consequently": "The roads were icy. As a result, 20 accidents were reported." "leads to" / "results in" / "causes": "Pollution leads to health problems." "so... that": "It rained so much that the river flooded." EFFECT → CAUSE (reverse): "The concert was cancelled. This was because the singer was ill."' },
          { title: 'Chain Reactions', type: 'tip', content: 'Many texts describe cause-effect CHAINS: A causes B, B causes C, C causes D. Example: Deforestation → less CO₂ absorbed → global temperature rises → ice caps melt → sea levels rise → coastal flooding. Understanding the chain helps you see the BIG PICTURE, not just individual facts. When reading, draw arrows: Cause → Effect → (becomes new Cause) → Effect. If you can trace the chain from start to finish, you fully understand the text.' },
          { title: 'Trace the Chain', type: 'exercise', question: '"The factory closed because demand for its products fell. When the factory closed, 500 people lost their jobs. Many of these workers could not find new employment, so they had less money to spend in local shops. As a result, several shops in the town also closed. The town\'s population began to decline as people moved away to find work."', answer: 'Chain: Demand fell → Factory closed → 500 lost jobs → Less spending in shops → Shops closed → Population declined as people left. This is a 5-step chain. The initial cause (falling demand) led to a cascade of effects. Each effect became the cause of the next problem — a common pattern in economics, science, and history texts.', answerExplanation: 'The connectors map the chain: "because" (cause), "When" (trigger), "so" (effect), "As a result" (consequence), "as" (reason for moving). Tracing cause-effect chains is essential for understanding news articles about economics, climate, health, and politics.' },
        ],
        keyTakeaways: ['"Because/since/due to" introduce CAUSES; "therefore/as a result" introduce EFFECTS', 'Many texts have cause-effect CHAINS — A→B→C→D', 'Trace the full chain to understand the big picture, not just individual facts'],
      },
      // # ─── Lesson 8: Reading Process Descriptions ───
      { id: 'b1-reading-processes', title: 'Reading Process Descriptions', description: 'Understand texts that explain how something works or how something is made.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Follow sequential processes with passive voice', 'Understand technical processes explained for general readers', 'Identify input, steps, and output'],
        sections: [
          { title: 'Process Language', type: 'rule', content: 'Processes describe HOW something happens, step by step. They use: PASSIVE VOICE: "The beans are roasted" (not "Someone roasts the beans"). Focus is on WHAT HAPPENS, not WHO does it. SEQUENCE WORDS: First, ... Then, ... Next, ... After that, ... Subsequently, ... Finally, ... "Once [step 1 is done], [step 2 begins]." "The mixture is then heated to 200°C." "At this stage, the product is inspected for quality." Every process has: INPUT (raw materials, ingredients) → STEPS (what happens) → OUTPUT (the final product).' },
          { title: 'Reading Passive Voice', type: 'tip', content: 'Passive voice is very common in process descriptions: Active: "Workers pick the coffee beans." (focus on workers) Passive: "The coffee beans are picked." (focus on beans) Why passive? Because in processes, WHO does it is less important than WHAT is done. Passive structure: [subject] + [is/are/was/were] + [past participle] "The water is filtered." "The data was analysed." "The products are shipped worldwide." If passive confuses you, mentally add "by someone" at the end: "The beans are roasted [by someone]." This confirms it\'s passive.' },
          { title: 'Follow This Process', type: 'exercise', question: '"How chocolate is made: First, cacao pods are harvested from trees. The pods are opened and the beans are removed. The beans are then fermented for 5-7 days to develop flavour. After fermentation, they are dried in the sun. The dried beans are roasted at around 130°C. Once roasted, the shells are removed and the beans are ground into a paste called \'cacao liquor.\' Finally, sugar and milk are added to create milk chocolate."', answer: 'Input: Cacao pods from trees. Steps: (1) Pods harvested → (2) Opened, beans removed → (3) Fermented 5-7 days → (4) Sun-dried → (5) Roasted at 130°C → (6) Shells removed, beans ground into cacao liquor → (7) Sugar and milk added. Output: Milk chocolate. The entire text uses passive voice — the focus is on what happens to the beans, not who does it.', answerExplanation: 'Seven steps, all in passive voice ("are harvested," "are removed," "are roasted"). The sequence words (First, then, After, Once, Finally) guide you through the order. Understanding process descriptions is essential for science, manufacturing, and IELTS/PTE writing tasks.' },
        ],
        keyTakeaways: ['Process descriptions use passive voice: "The beans are roasted" (focus on the action, not the person)', 'Every process has INPUT → STEPS → OUTPUT', '"Once [step A is done], [step B begins]" links steps in sequence'],
      },
      // # ─── Lesson 9: Reading for Gist vs Detail ───
      { id: 'b1-reading-gist-vs-detail', title: 'Reading for Gist vs Reading for Detail', description: 'Switch between big-picture reading and close detail reading as needed.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Read for gist (the overall message) quickly', 'Read for detail (specific facts) accurately', 'Know which approach to use and when to switch'],
        sections: [
          { title: 'Gist vs Detail', type: 'rule', content: 'GIST (the big picture): "What is this text ABOUT?" Read: title, first/last paragraphs, first sentence of each paragraph. Speed: fast — 1-2 minutes for a full article. Use when: deciding if a text is relevant, previewing before detailed reading, answering "What is the main idea?" DETAIL (the specifics): "What EXACTLY does it say about X?" Read: carefully, word by word, in the relevant section. Speed: slow — re-read if needed. Use when: answering specific questions, checking facts, understanding instructions. Skilled readers switch between gist and detail WITHIN the same text.' },
          { title: 'The Preview-Read-Review Method', type: 'tip', content: 'PREVIEW (30 seconds): skim the title, headings, images, first and last paragraphs. Ask: "What is this about? Do I need to read it?" READ (at the right speed): if you need the gist → read first sentences of paragraphs. If you need details → read the relevant section carefully. REVIEW (30 seconds): look back at what you read. Ask: "What were the main points? Can I summarise this?" This 3-step method works for articles, textbook chapters, reports, and emails. It prevents both "reading too slowly" (wasting time) and "reading too fast" (missing key information).' },
          { title: 'Practice Both', type: 'exercise', question: '"The Rise of Electric Cars. Electric vehicle sales grew by 35% in 2025, reaching 18 million units worldwide. China leads the market with 60% of global sales. Battery costs have dropped 80% since 2015, making EVs affordable for more buyers. However, charging infrastructure remains a challenge — only 2.7 million public chargers exist globally, compared to 150,000 petrol stations. Governments are investing heavily: the EU has committed €5 billion to charging networks by 2030." (a) What is the gist? (b) How many public chargers exist?', answer: '(a) Gist: Electric car sales are growing rapidly thanks to cheaper batteries, but charging infrastructure is still a major challenge. (b) Detail: 2.7 million public chargers exist globally. For the gist, you only needed the headline + first sentence + "However" sentence. For the detail, you needed to scan for the specific number.', answerExplanation: 'The gist question required reading broadly (growth + challenge). The detail question required scanning for one specific number. In a real situation, you would skim for gist first, then scan for details only if you need them. Using both skills together is efficient reading.' },
        ],
        keyTakeaways: ['Gist = "What is it about?" (read fast, main ideas). Detail = "What exactly?" (read carefully, specific facts)', 'Preview-Read-Review: 30s preview, read at the right speed, 30s review', 'Switch between gist and detail WITHIN the same text — that\'s skilled reading'],
      },
      // # ─── Lesson 10: Reading Advice Columns ───
      { id: 'b1-reading-advice-columns', title: 'Reading Advice Columns & Problem-Solution Texts', description: 'Understand texts that present a problem and offer solutions.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Identify the problem clearly', 'Follow the proposed solution(s)', 'Evaluate whether the advice is good or not'],
        sections: [
          { title: 'Problem-Solution Structure', type: 'rule', content: 'Many texts follow this pattern: SITUATION: background context. "More people are working from home than ever before." PROBLEM: what is wrong. "Many workers struggle with loneliness and poor work-life balance." SOLUTION: what should be done. "Companies should offer regular in-person team days." EVALUATION: does the solution work? "Early results show that monthly team days reduce loneliness by 30%." Signal phrases: Problem: "The issue is...", "The challenge is...", "The difficulty lies in..." Solution: "One solution is...", "To address this...", "A possible approach would be..."' },
          { title: 'Evaluating Advice', type: 'tip', content: 'Not all advice is good. Ask: Is it PRACTICAL? "Quit your job" is not helpful if you have bills to pay. Is it EVIDENCE-BASED? Does the writer cite research or just personal opinion? Does it consider SIDE EFFECTS? "Work 14 hours a day to get promoted" ignores burnout. Is it SPECIFIC? "Try harder" is vague. "Study for 30 minutes before bed using flashcards" is actionable. Does it match YOUR situation? Advice for a CEO may not apply to a student. Good advice is specific, practical, evidence-based, and considers trade-offs.' },
          { title: 'Evaluate This Advice', type: 'exercise', question: '"Dear Ask Amy, I can\'t sleep at night. I lie awake for hours worrying about work. — Tired Tom. Dear Tom, Try these: 1. No screens 1 hour before bed. 2. Write your worries in a notebook before sleeping — this \'empties\' your mind. 3. Exercise in the morning, not the evening. 4. If it continues for more than 2 weeks, see a doctor. Research shows that writing worries down reduces sleep onset time by 40%." Is this good advice?', answer: 'Yes, this is strong advice because: (1) It is specific and actionable (not "just relax"). (2) It includes a research-backed technique (writing worries = 40% faster sleep). (3) It addresses the underlying cause (work worry). (4) It has an escalation path ("see a doctor" if it persists). (5) The "no evening exercise" tip addresses a common mistake. One improvement: it could ask about caffeine intake, which is a major sleep disruptor.', answerExplanation: 'Evaluating advice is a critical reading skill. The advice passes the test: specific, evidence-based, practical, considers when to seek professional help. Identifying what\'s MISSING (caffeine) shows advanced reading comprehension — you\'re thinking beyond the text.' },
        ],
        keyTakeaways: ['Problem-solution texts follow: Situation → Problem → Solution → Evaluation', 'Good advice is specific, practical, evidence-based, and considers side effects', 'Always ask: "What is MISSING from this advice?" — no text covers everything'],
      },
      // # ─── Lesson 11: Reference & Pronoun Tracking ───
      { id: 'b1-reading-reference-tracking', title: 'Reference & Pronoun Tracking', description: 'Track what "it", "this", "they", and other pronouns refer to in longer texts.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Identify what pronouns refer to in context', 'Track references across multiple sentences', 'Avoid confusion when texts use "this", "these", "such"'],
        sections: [
          { title: 'Reference Words', type: 'rule', content: 'Reference words point BACK to something already mentioned: PRONOUNS: he, she, it, they, we, them, his, her, its, their. "Maria studied hard. She passed the exam." (She = Maria) DEMONSTRATIVES: this, that, these, those. "The company laid off 200 workers. This caused widespread anger." (This = the layoffs) SUCH: "Doctors, nurses, and paramedics. Such professionals are essential." (Such professionals = doctors, nurses, paramedics) THE + NOUN SUMMARY: "The government increased taxes. The decision was unpopular." (The decision = increasing taxes) "One/ones": "I tried the red shoes but preferred the blue ones." (ones = shoes)' },
          { title: 'When Tracking Gets Hard', type: 'tip', content: 'Pronouns get confusing when multiple nouns could be the referent: "John told Peter that he was wrong." — who is "he"? John or Peter? Usually: "he" = the SUBJECT (John). But context matters — read the next sentence for clarification. "It" can refer to: a thing ("The car broke down. It was old."), a situation ("He lost his job. It was devastating."), or an idea ("She suggested working from home. It seemed like a good idea."). When confused, go back to the LAST noun that fits grammatically and logically. If still unclear, the writer made a mistake (it happens).' },
          { title: 'What Does "It" Refer To?', type: 'exercise', question: '"The company launched a new product last month. Sales were disappointing, however, and critics called the design outdated. The CEO acknowledged that it needed improvement and promised a redesigned version within six months. This reassured investors, and the share price recovered." What do "it" and "This" refer to?', answer: '"It" = the product (or the design). The CEO said the product/design needed improvement. "This" = the CEO\'s promise to redesign within six months. The promise (not the product) reassured investors. "It" looks back to "the design/product." "This" looks back to the entire previous sentence (the CEO\'s acknowledgement and promise).', answerExplanation: '"This" often refers to an entire IDEA or SITUATION, not just one noun. The investors were reassured by the CEO\'s promise, not by the product itself. Tracking references precisely prevents misunderstanding — a common cause of wrong answers in reading exams.' },
        ],
        keyTakeaways: ['"It" usually refers to the last singular noun. "They" = the last plural noun.', '"This" often refers to an entire situation or idea, not just one word', 'When confused, go back and find the last noun that fits both grammar and meaning'],
      },
      // # ─── Lesson 12: Reading Charts & Graphs in Articles ───
      { id: 'b1-reading-charts-in-articles', title: 'Reading Charts & Graphs Within Articles', description: 'Understand how writers use data visualisations to support their arguments.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Read line graphs showing trends over time', 'Understand how charts support or contradict the text', 'Describe data trends in words'],
        sections: [
          { title: 'Chart Reading at B1', type: 'rule', content: 'LINE GRAPH: shows change over TIME. X-axis = time (years, months). Y-axis = the measurement (sales, temperature, population). A rising line = increase / growth. A falling line = decrease / decline. A flat line = stability / no change. A sharp change = sudden / dramatic. A gradual change = slow / steady. BAR CHART comparisons: "taller bar = larger value." Always check: (1) The TITLE — what is being measured? (2) The AXES — what do the numbers mean? (3) The UNITS — %, millions, £, °C? (4) The SCALE — does it start at 0 or is it "zoomed in"?' },
          { title: 'Charts Can Mislead', type: 'tip', content: 'Watch for tricks: TRUNCATED AXIS: Y-axis starts at 90 instead of 0. A change from 92 to 95 looks huge, but it\'s only 3%. CHERRY-PICKED TIME RANGE: 2022-2025 shows growth, but 2020-2025 shows a recovery from a crash. MISSING CONTEXT: "Our product is #1!" — #1 out of how many? In what category? 3D CHARTS: depth distorts size — flat 2D is more accurate. CORRELATION ≠ CAUSATION: "Ice cream sales and drowning rates both increase in summer." Ice cream doesn\'t cause drowning — summer heat causes both. Always ask: "What is this chart NOT showing me?"' },
          { title: 'Describe This Trend', type: 'exercise', question: 'A line graph shows UK electric car sales: 2020: 100K, 2021: 190K, 2022: 270K, 2023: 310K, 2024: 350K, 2025: 380K. Describe the trend.', answer: 'Electric car sales in the UK increased steadily from 100,000 in 2020 to 380,000 in 2025, almost quadrupling over five years. The growth was fastest between 2020 and 2022 (from 100K to 270K — nearly tripling). After 2022, growth slowed — the increases became smaller each year (80K, then 40K, then 30K). The trend suggests the market is maturing — early rapid growth is giving way to a steadier, slower increase.', answerExplanation: 'A good data description includes: the overall trend (increased), specific numbers (100K to 380K), the time period (2020-2025), and a pattern observation (growth slowing). This is exactly the language needed for IELTS Writing Task 1 and B1+ academic reading.' },
        ],
        keyTakeaways: ['Always check: title, axes, units, and whether the scale starts at 0', '"Sharp" = sudden change, "Gradual" = slow change, "Steady" = consistent direction', 'Charts can mislead — ask "What is this chart NOT showing me?"'],
      },
      // # ─── Lesson 13: Summarising What You Read ───
      { id: 'b1-reading-summarising', title: 'Summarising What You Read', description: 'Condense a long text into its essential points — a key academic and professional skill.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Identify the main points of a text', 'Write a summary in your own words', 'Distinguish main points from supporting details'],
        sections: [
          { title: 'How to Summarise', type: 'rule', content: 'A summary is a SHORT version of a longer text. It includes ONLY the main points — not examples, details, or quotes. Steps: (1) Read the text fully. (2) Identify the topic sentence of each paragraph. (3) List the main points (usually 3-5). (4) Write them in YOUR OWN WORDS — do not copy sentences. (5) Connect them with simple connectors (and, but, however, because). A good summary is: 20-25% the length of the original. In your own words (paraphrased). Covers ALL main points, not just the first one. Objective — no personal opinion added.' },
          { title: 'Main Points vs Details', type: 'tip', content: 'MAIN POINT: the key idea you MUST include. "Remote work increases productivity." DETAIL: supports the main point — can be omitted in a summary. "A Stanford study of 16,000 workers found a 13% increase." EXAMPLE: illustrates a point — usually omitted in summaries. "For instance, Company X saw output rise by 20% after going remote." QUOTE: someone\'s exact words — paraphrase in summaries. If removing a piece of information changes the overall message, it is a main point. If removing it leaves the message intact, it is a detail.' },
          { title: 'Summarise This Paragraph', type: 'exercise', question: '"Fast fashion is one of the biggest environmental problems of our time. The industry produces 92 million tonnes of textile waste annually. Manufacturing a single cotton T-shirt requires 2,700 litres of water. Workers in developing countries are paid as little as $2 per day. Environmental groups argue that consumers must change their buying habits, favouring quality over quantity." Summarise in 1-2 sentences.', answer: 'Fast fashion causes severe environmental damage through massive waste and water consumption, and exploits workers in developing countries. Environmental groups recommend that consumers prioritise quality over quantity to reduce harm.', answerExplanation: 'The summary captures: the problem (environmental damage + worker exploitation) and the solution (change buying habits). The specific numbers (92 million tonnes, 2,700 litres, $2/day) are details — they SUPPORT the main points but are not needed in the summary. "In your own words" means you paraphrase, not copy.' },
        ],
        keyTakeaways: ['A summary = main points only, in your own words, 20-25% of the original length', 'If removing it changes the message → main point. If not → detail.', 'Never add your own opinion to a summary — report what the TEXT says'],
      },
      // # ─── Lesson 14: Reading Formal Letters & Notices ───
      { id: 'b1-reading-formal-letters', title: 'Reading Formal Letters & Official Notices', description: 'Understand letters from banks, landlords, employers, and government offices.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Decode formal language into plain English', 'Identify what action is required from you', 'Understand deadlines and consequences in official letters'],
        sections: [
          { title: 'Formal Letter Phrases Decoded', type: 'rule', content: '"I am writing to inform you that..." = I need to tell you something. "Please be advised that..." = please note / be aware. "We regret to inform you..." = bad news is coming. "Your account has been overdrawn." = you have spent more money than you have. "You are hereby notified that..." = official legal language — pay attention. "Failure to respond by [date] will result in..." = if you don\'t reply by this date, something bad will happen. "We would be grateful if you could..." = please do this (politely phrased, but it\'s not optional). "Please do not hesitate to contact us." = you can call/email if you have questions.' },
          { title: 'Finding the Action Required', type: 'tip', content: 'Formal letters often bury the important parts in polite language. Always find: (1) WHY are they writing? (first paragraph) (2) WHAT do they want you to DO? (middle paragraphs) (3) BY WHEN? (deadline — often in the last paragraphs) (4) WHAT HAPPENS if you don\'t? (consequences) Example: "We are writing regarding your tenancy at 42 Park Lane. Please be aware that your lease expires on 30 September 2026. Should you wish to renew, please contact our office by 15 September." → Action: contact them. Deadline: 15 September. Consequence (implied): you may lose your home.' },
          { title: 'Decode This Letter', type: 'exercise', question: '"Dear Mr Park, We are writing to advise you that your annual vehicle insurance policy is due for renewal on 15 October 2026. Your new premium will be £847.50, an increase of £112 from your current policy. If you wish to continue your cover, no action is required — your policy will automatically renew. Should you wish to cancel, please notify us in writing by 10 October. Failure to cancel by this date will result in your payment being processed. Yours sincerely, ABC Insurance."', answer: 'Why: Insurance renewal notice. Action needed: DECIDE — if you want to keep it, do nothing (auto-renews). If you want to cancel, write to them before 10 October. Price: £847.50 (up £112 from last year). Deadline: 10 October to cancel. Consequence: if you don\'t cancel by 10 October, they will charge you £847.50. Trap: "no action is required" sounds passive but it means they WILL charge you. If the new price is too high, you must actively cancel.', answerExplanation: '"No action required" is cleverly designed — it sounds easy but means you will be charged unless you actively cancel. Many official letters use this "opt-out" structure. Always check: "What happens if I do NOTHING?" In this case, doing nothing = paying £847.50.' },
        ],
        keyTakeaways: ['"We regret to inform you" = bad news. "No action is required" = it will happen automatically.', 'Always find: WHY, WHAT to do, BY WHEN, WHAT IF you don\'t', '"Failure to [do X] by [date] will result in [consequence]" = a deadline with penalties'],
      },
      // # ─── Lesson 15: Reading Argumentative Essays ───
      { id: 'b1-reading-argumentative-essays', title: 'Reading Argumentative Essays', description: 'Follow structured arguments with thesis, evidence, counter-arguments, and conclusions.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Identify the thesis statement', 'Distinguish between arguments and counter-arguments', 'Evaluate the strength of evidence used'],
        sections: [
          { title: 'Essay Structure', type: 'rule', content: 'INTRODUCTION: background + thesis statement. "While many argue X, this essay will demonstrate that Y." BODY PARAGRAPH 1: First argument + evidence. BODY PARAGRAPH 2: Second argument + evidence. COUNTER-ARGUMENT: "However, critics argue that..." REBUTTAL: "Nevertheless, this argument fails because..." CONCLUSION: restates thesis + final thought. Key phrases: "It can be argued that..." "Evidence suggests that..." "On the contrary..." "In conclusion, the evidence clearly shows..."' },
          { title: 'Evaluating Evidence', type: 'tip', content: 'Strong evidence: published research with numbers ("A 2025 WHO study of 50,000 people found..."), expert testimony from relevant fields, official statistics from reliable sources, multiple sources saying the same thing. Weak evidence: personal stories (one person\'s experience ≠ everyone\'s), unnamed sources ("some people say..."), outdated data (a 1990 study about internet use), false equivalence ("some scientists disagree" — but 97% agree). When reading an essay, ask: "Would a different piece of evidence disprove this claim?"' },
          { title: 'Analyse This Essay Extract', type: 'exercise', question: '"University education should be free. A 2024 OECD report found that countries with free university education have higher rates of social mobility and lower income inequality. Furthermore, graduates contribute more in lifetime taxes than the cost of their education. Critics argue that free university would be too expensive for governments. However, the OECD data shows that the long-term economic return exceeds the initial investment by 300%."', answer: 'Thesis: University education should be free. Argument 1: Free education → higher social mobility, lower inequality (OECD report). Argument 2: Graduates pay back more in taxes than their education costs. Counter-argument: Too expensive for governments. Rebuttal: Long-term return exceeds cost by 300% (OECD data). Strength: Uses specific, named, reputable source (OECD). Includes numbers (300%). Addresses the main counter-argument. Weakness: Only one source — other studies might disagree.', answerExplanation: 'This is a well-structured argument: claim + evidence + counter-argument + rebuttal. The OECD is a credible source. The 300% return figure is specific and verifiable. The weakness is relying on one source — a stronger essay would cite 2-3 independent studies.' },
        ],
        keyTakeaways: ['Thesis = the main claim. Counter-argument = the opposing view. Rebuttal = why it\'s wrong.', 'Strong evidence: named sources, specific numbers, multiple studies', 'One source is not enough — good arguments have multiple, independent sources'],
      },
      // # ─── Lesson 16: Understanding Text Organisation Patterns ───
      { id: 'b1-reading-text-organisation', title: 'Understanding Text Organisation Patterns', description: 'Recognise how different texts are organised — chronological, topical, compare/contrast, problem/solution.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Identify the four main text organisation patterns', 'Use the pattern to predict what comes next', 'Choose the right reading strategy for each pattern'],
        sections: [
          { title: 'Four Organisation Patterns', type: 'rule', content: 'CHRONOLOGICAL: events in time order. Signal words: first, then, next, in 1990, after, finally. Used in: history, biographies, narratives, processes. COMPARE/CONTRAST: similarities and differences between two+ things. Signal words: similarly, however, whereas, on the other hand, both, unlike. Used in: product reviews, debates, analysis. CAUSE/EFFECT: one thing leads to another. Signal words: because, therefore, as a result, consequently, leads to. Used in: science, economics, health articles. PROBLEM/SOLUTION: presents a problem then proposes fixes. Signal words: the issue is, one solution, to address this, the challenge. Used in: editorials, advice, policy documents.' },
          { title: 'Why Pattern Recognition Matters', type: 'tip', content: 'When you identify the pattern, you can: PREDICT what comes next (after a problem, expect a solution). READ FASTER (you know where the key information will be). TAKE BETTER NOTES (organise by the pattern — timeline, table, diagram). ANSWER QUESTIONS more accurately (know where to look for the answer). Many texts MIX patterns: an article might use chronological order in the introduction, then compare/contrast in the body, then problem/solution in the conclusion. The dominant pattern is the one used for the MAIN argument.' },
          { title: 'Identify the Pattern', type: 'exercise', question: '(a) "Electric cars are quieter than petrol cars. However, they have a shorter range. Both types require regular maintenance, but EV maintenance is generally cheaper." (b) "In 1903, the Wright brothers flew for the first time. By 1927, Lindbergh crossed the Atlantic. In 1969, humans landed on the moon." (c) "Traffic congestion costs London £5 billion a year. One solution is congestion charging, which reduced central London traffic by 25%."', answer: '(a) Compare/Contrast — signal words: "quieter than," "However," "Both," "but." Compares electric vs petrol cars. (b) Chronological — signal words: "In 1903," "By 1927," "In 1969." Events in time order. (c) Problem/Solution — the problem (congestion costs £5B) then the solution (congestion charging) with evidence (25% reduction).', answerExplanation: 'Once you identify the pattern, you know what to expect. Compare/contrast → look for a table of differences. Chronological → follow the timeline. Problem/solution → find what the fix is and whether it works. Pattern recognition is one of the most powerful reading strategies.' },
        ],
        keyTakeaways: ['Four patterns: chronological, compare/contrast, cause/effect, problem/solution', 'Signal words tell you the pattern — "however" = contrast, "as a result" = cause/effect', 'Knowing the pattern helps you predict, read faster, and find answers more accurately'],
      },
      // # ─── Lesson 17: Reading Short Fiction ───
      { id: 'b1-reading-short-fiction', title: 'Reading Short Fiction', description: 'Enjoy and understand short stories — plot, characters, and themes.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Follow a plot with beginning, middle, and end', 'Understand character motivation and development', 'Identify the theme or moral of a story'],
        sections: [
          { title: 'Story Elements at B1', type: 'rule', content: 'PLOT: the sequence of events. Beginning (setup) → Rising action (tension builds) → Climax (the turning point) → Falling action (consequences) → Resolution (ending). CHARACTER: protagonist (main character) vs antagonist (the opposition). Motivation = WHY the character does what they do. Development = how they CHANGE during the story. SETTING: where and when. Can reflect mood — a dark, rainy night creates suspense. THEME: the deeper meaning or lesson. Not stated directly — you must infer it. "Love conquers all." "Honesty is more important than success." "Appearances can be deceiving."' },
          { title: 'Reading for Theme', type: 'tip', content: 'The theme is the "big idea" the author wants you to think about. It is NOT: the plot ("A man finds a wallet") or the topic ("honesty"). It IS: a statement about life ("Being honest is difficult but rewarding"). To find the theme, ask: (1) What does the main character learn? (2) How does the character change from beginning to end? (3) What message does the ending send? (4) If you could describe the story\'s lesson in one sentence, what would it be? Multiple themes are possible — readers may disagree, and that\'s fine.' },
          { title: 'Identify the Theme', type: 'exercise', question: '"Anna was the fastest runner in her school. She never practised because she always won easily. At the national championship, she was confident she would win again. But a girl from a small rural school — someone Anna had never heard of — beat her by three seconds. Anna was shocked. She realised she had been arrogant. The next year, she trained every day. She won the nationals — but more importantly, she won with humility."', answer: 'Theme: Natural talent is not enough — hard work and humility are necessary for lasting success. Anna\'s journey: confident (arrogant) → defeated → humbled → trained hard → won with humility. She changed from someone who relied on talent to someone who earned success through effort. The word "more importantly" at the end signals the theme — the author values humility over victory.', answerExplanation: 'The theme is NOT "a girl wins a race" (that\'s the plot). It\'s about the transformation from arrogance to humility. The phrase "more importantly, she won with humility" is the author\'s way of telling you what matters. Themes apply beyond the story — this lesson applies to careers, relationships, and life.' },
        ],
        keyTakeaways: ['Theme ≠ plot. Plot = what happens. Theme = what it means about life.', 'To find the theme: how does the main character change from start to end?', '"More importantly" and similar phrases in endings often signal the theme directly'],
      },
      // # ─── Lesson 18: Reading Interviews ───
      { id: 'b1-reading-interviews', title: 'Reading Interviews & Q&A Formats', description: 'Follow interview texts — questions, answers, and the interviewer\'s editorial framing.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Distinguish between the interviewer\'s framing and the interviewee\'s actual words', 'Identify key quotes and their significance', 'Understand how context shapes interview interpretation'],
        sections: [
          { title: 'Interview Text Structure', type: 'rule', content: 'INTRODUCTION: the journalist sets the scene. "Dr Smith has spent 20 years studying..." (this is the JOURNALIST\'s framing, not Dr Smith\'s words). Q&A: the actual interview. Q: journalist\'s question. A: the interviewee\'s answer. Sometimes formatted as: bold name + colon: "Interviewer: What inspired you?" "Dr Smith: I grew up near a polluted river..." PULL QUOTES: a short, powerful quote highlighted in bigger text. The journalist chooses this — it represents their editorial emphasis, not necessarily the interviewee\'s main point. EDITORIAL COMMENTS: inserted between questions. "[Smith pauses, choosing her words carefully]" — this is the journalist\'s interpretation.' },
          { title: 'Reading Interviews Critically', type: 'tip', content: 'Interviews are EDITED. The journalist: chooses which questions to include (and which to cut), selects which answers to print (often shortened), adds editorial framing that shapes how you interpret the answers, picks the pull quote that supports their angle. The same interview can become: "Expert supports new policy" or "Expert warns of policy risks" — depending on which quotes the journalist uses. When reading interviews, ask: "Am I hearing the interviewee\'s view, or the journalist\'s interpretation of their view?"' },
          { title: 'Whose View Is This?', type: 'exercise', question: '"Controversial AI expert Dr Chen has been criticised for her bold claims about artificial intelligence. When asked about job losses, she replied: \'AI will create more jobs than it destroys — but different kinds of jobs. We need to invest in retraining.\' Despite her optimism, many economists disagree." Whose views are represented? How does the framing affect your reading?', answer: 'Dr Chen\'s view: AI will create more jobs than it destroys, but retraining is needed (direct quote). Journalist\'s framing: calls her "controversial," notes she has been "criticised" for "bold claims," and adds "many economists disagree." The framing makes Dr Chen sound unreliable before you even read her answer. Without the framing, her quote sounds reasonable and moderate. The word "despite" dismisses her optimism.', answerExplanation: '"Controversial" and "bold claims" are editorial judgements, not facts. "Many economists disagree" is vague — how many? Who? The journalist is telling you not to trust Dr Chen before she even speaks. A neutral framing would be: "AI researcher Dr Chen says..." Reading interviews critically means separating the person\'s actual words from the journalist\'s editorialising.' },
        ],
        keyTakeaways: ['Interviews are EDITED — the journalist chooses what to include and how to frame it', 'Direct quotes (in quotation marks) = the person\'s actual words. Everything else = the journalist\'s framing', '"Controversial," "bold claims," "despite" = editorial language that shapes your interpretation'],
      },
      // # ─── Lesson 19: Reading Instructions with Conditions ───
      { id: 'b1-reading-conditional-instructions', title: 'Reading Instructions with Conditions & Exceptions', description: 'Follow complex instructions that include if-then rules, exceptions, and special cases.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Parse if-then conditions accurately', 'Understand exceptions and special cases', 'Apply multi-condition rules to specific scenarios'],
        sections: [
          { title: 'Conditional Language in Instructions', type: 'rule', content: 'Simple condition: "If you are under 18, you need parental consent." Double condition: "If you are under 18 AND travelling alone, you need a signed letter." Exception: "All passengers must have a valid passport, EXCEPT EU citizens travelling within the EU." Unless: "You cannot enter unless you have a ticket." (= you CAN enter IF you have a ticket). "Unless" = "if not." Provided / As long as: "You may use the pool provided you shower first." (= you CAN use it IF you shower).' },
          { title: 'Multiple Conditions', type: 'tip', content: 'Some rules have AND conditions (all must be true) vs OR conditions (any one is enough): AND: "If you are over 18 AND have a valid ID AND have purchased a ticket, you may enter." (All three required.) OR: "Payment accepted by credit card, debit card, OR cash." (Any one is fine.) NOT: "No food, drinks, or cameras allowed." (None of these permitted.) Reading these precisely is critical for: visa applications, insurance policies, return policies, academic regulations, employment contracts. One word can change everything: "and" vs "or," "must" vs "may," "before" vs "after."' },
          { title: 'Apply the Rules', type: 'exercise', question: '"Returns policy: Items may be returned within 30 days of purchase. You must have the original receipt. Electrical items may only be returned if unopened. Sale items are non-refundable but may be exchanged for items of equal or greater value. Items purchased online may be returned to any store or by post." You bought headphones (electrical) on sale 3 weeks ago. You opened them and they don\'t fit. Can you return them?', answer: 'Partially. You are within 30 days ✓. BUT: (1) They are electrical AND opened — electrical items can only be returned if UNOPENED ✗. (2) They are sale items — non-refundable ✗, but you MAY exchange for equal or greater value. So: You cannot get a refund. You might not be able to exchange either because the "unopened" rule for electrical items may override the exchange option. You should ask the store — the policy is ambiguous about whether the electrical rule or the sale exchange rule takes priority.', answerExplanation: 'This is a real-world reading challenge. Two rules potentially conflict: the electrical rule (must be unopened) and the sale rule (can exchange). Policies are often ambiguous at the edges. The reading skill here is recognising the ambiguity rather than assuming one rule wins. In real life, you would need to contact the store to clarify.' },
        ],
        keyTakeaways: ['"Unless" = "if not." "Provided" = "if." "Except" = an exclusion from the rule.', 'AND = all conditions required. OR = any one is enough.', 'When two rules conflict, the policy is ambiguous — ask for clarification'],
      },
      // # ─── Lesson 20: Reading Health & Lifestyle Articles ───
      { id: 'b1-reading-health-articles', title: 'Reading Health & Lifestyle Articles', description: 'Critically read health advice — separating evidence-based information from trends and myths.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Distinguish evidence-based health claims from opinions', 'Understand hedging language (may, might, could, suggests)', 'Identify red flags in health misinformation'],
        sections: [
          { title: 'Hedging Language in Health Writing', type: 'rule', content: 'Scientific writing uses careful language: "may" / "might" / "could": "Coffee may reduce the risk of diabetes." = possible, not certain. "suggests" / "indicates": "The study suggests a link between..." = evidence points to, but not proven. "is associated with": "Exercise is associated with lower depression." = they happen together, but one doesn\'t necessarily CAUSE the other. "further research is needed": = we\'re not sure yet. Headlines often drop the hedging: Study: "Coffee may reduce diabetes risk." Headline: "COFFEE PREVENTS DIABETES!" — this is misleading.' },
          { title: 'Red Flags in Health Claims', type: 'tip', content: 'Be suspicious if: the article claims a MIRACLE CURE ("This one food cures cancer!"), no sources or studies are cited, the writer is selling something (supplements, a diet book), it contradicts mainstream science ("Doctors don\'t want you to know..."), it uses absolute language ("always," "never," "guaranteed"), the study is on MICE, not humans (results may not transfer), the sample size is tiny ("a study of 12 people"), the claim is based on ONE study (science needs replication). Reliable health sources: WHO, NHS, Mayo Clinic, PubMed, peer-reviewed journals.' },
          { title: 'Evaluate This Health Claim', type: 'exercise', question: '"A new study from Harvard University found that people who eat dark chocolate at least three times a week MAY have a 20% lower risk of heart disease. The study followed 50,000 people over 10 years. However, researchers noted that chocolate eaters also tended to exercise more and have higher incomes, which could partly explain the results."', answer: 'This is relatively reliable because: large study (50,000 people), long duration (10 years), credible institution (Harvard), uses hedging ("may"). BUT the key weakness is the confounding variables: chocolate eaters also exercised more and had higher incomes — these factors ALSO reduce heart disease risk. So it might be exercise and wealth, not chocolate, that explains the results. The claim is plausible but not proven — exactly what "may" signals.', answerExplanation: 'This is how real science reads. "May" is honest — the researchers are not claiming chocolate definitely prevents heart disease. The confounding variables (exercise, income) are crucial: CORRELATION (eating chocolate and lower heart disease occur together) does not prove CAUSATION (chocolate causes lower heart disease). Understanding this distinction is essential for reading health content critically.' },
        ],
        keyTakeaways: ['"May," "might," "suggests" = possible, not proven. Headlines often drop these.', 'Correlation ≠ causation — two things happening together doesn\'t mean one causes the other', 'Red flags: miracle claims, no sources, selling something, "doctors don\'t want you to know"'],
      },
      // # ─── Lesson 21: Reading with a Purpose ───
      { id: 'b1-reading-with-purpose', title: 'Reading with a Purpose — Task-Based Reading', description: 'Read to accomplish a specific goal — not just to understand the text.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Define your reading purpose before starting', 'Extract only relevant information', 'Ignore irrelevant sections efficiently'],
        sections: [
          { title: 'Purpose-Driven Reading', type: 'rule', content: 'Before reading anything, ask: "WHY am I reading this?" Possible purposes: To find a specific fact (scan). To understand the main idea (skim). To learn a new skill (read carefully + take notes). To make a decision (compare options). To answer exam questions (read questions first, then the text). To enjoy (read at your own pace, no pressure). Your purpose determines your strategy. Reading a novel and reading an insurance policy require completely different approaches — but many people read everything the same way.' },
          { title: 'Questions-First Strategy', type: 'tip', content: 'For exams and research: read the QUESTIONS before the text. Why? You know what to look for. You can ignore irrelevant sections. You read actively, not passively. You save time. Example: Question asks "What percentage of workers prefer remote work?" → Scan the text for a percentage near the word "remote." You don\'t need to understand the entire article — just find and verify that one answer. This strategy can cut reading time by 40-50% in exam conditions.' },
          { title: 'Read with Different Purposes', type: 'exercise', question: '"The City Art Museum is open Tuesday to Sunday, 10 AM - 6 PM (closed Mondays). Admission: Adults £12, Students £8, Under 5s Free. The current exhibition \'Light & Shadow\' by Japanese artist Yuki Tanaka runs until 15 September. The museum café serves organic lunch from 12-3 PM. Guided tours available at 11 AM and 2 PM (£5 extra). Wheelchair accessible. Free parking on Sundays." Give different answers for: (a) planning a visit with a 3-year-old, (b) writing an essay about Yuki Tanaka.', answer: '(a) Visit with a 3-year-old: Open Tue-Sun, 10-6. Under 5s free — no need to pay for the child. Wheelchair accessible (pushchair-friendly too). Free parking on Sundays. Café has organic lunch 12-3. Guided tour at 11 or 2 (but maybe too long for a toddler). (b) Essay about Yuki Tanaka: The exhibition is called "Light & Shadow." It runs until 15 September. Yuki Tanaka is Japanese. Everything else (parking, café, prices) is irrelevant to an essay.', answerExplanation: 'Same text, different purposes, completely different information extracted. Purpose (a) needs practical logistics. Purpose (b) needs the artist\'s details. A reader without a purpose would read everything equally — wasting time on irrelevant details. Define your purpose before reading.' },
        ],
        keyTakeaways: ['Always ask "WHY am I reading this?" before you start', 'Read exam questions FIRST, then scan the text for answers', 'Same text + different purpose = different information matters'],
      },
      // # ─── Lesson 22: Reading Academic Texts ───
      { id: 'b1-reading-academic-texts', title: 'Introduction to Academic Reading', description: 'Start reading simplified academic texts — textbook chapters, research summaries, and reports.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Navigate academic text features (headings, abstracts, references)', 'Understand academic vocabulary at B1 level', 'Extract key findings from research summaries'],
        sections: [
          { title: 'Academic Text Features', type: 'rule', content: 'Academic texts have: TITLE: often long and specific. "The Effects of Sleep Deprivation on Academic Performance in University Students." ABSTRACT: a 100-200 word summary of the ENTIRE paper. Read this FIRST. INTRODUCTION: background + research question. METHODOLOGY: how the study was done. RESULTS: what they found (data, charts, statistics). DISCUSSION: what the results MEAN. CONCLUSION: summary + implications. REFERENCES: list of sources cited. At B1, focus on: the abstract, the introduction, and the conclusion. These give you 80% of the information in 20% of the reading time.' },
          { title: 'Academic Vocabulary at B1', type: 'tip', content: 'Common academic words to know: significant = important / statistically meaningful. participants = people in the study. methodology = how the research was done. findings = results. implications = what the results mean for the real world. limitations = weaknesses of the study. correlation = two things that happen together. hypothesis = the researcher\'s prediction. data = information collected (singular: datum, but "data" is used for both). sample = the group studied. variable = something that changes or is changed. These words appear in every academic field — learning them unlocks academic reading across subjects.' },
          { title: 'Read This Abstract', type: 'exercise', question: '"Abstract: This study examined the relationship between social media use and sleep quality in 500 university students aged 18-24. Participants completed questionnaires about their daily social media usage and sleep patterns. Results showed that students who used social media for more than 3 hours daily reported significantly poorer sleep quality (p<0.05). The findings suggest that excessive social media use may negatively impact sleep, though causation cannot be confirmed. Limitations include self-reported data and a single university sample." What are the key findings? What are the limitations?', answer: 'Key findings: Students using social media 3+ hours/day had significantly worse sleep quality. The relationship is statistically significant (p<0.05). Limitations: (1) Self-reported — people might not accurately report their usage or sleep. (2) Single university — results might not apply to all students everywhere. Important caveat: "causation cannot be confirmed" = they found a link but can\'t prove social media CAUSES poor sleep (maybe poor sleepers use more social media because they\'re awake).', answerExplanation: 'The abstract gives you everything: who (500 students), what (social media vs sleep), how (questionnaires), results (3+ hours = worse sleep), and limitations (self-reported, one university). Reading just the abstract saved you from reading a 5,000-word paper. "p<0.05" means there is less than a 5% chance the result is due to luck — this is the standard threshold for "statistically significant" in research.' },
        ],
        keyTakeaways: ['Read the abstract FIRST — it summarises the entire paper in 100-200 words', '"Significant" in academic writing means statistically meaningful, not just "important"', '"Causation cannot be confirmed" = they found a link but can\'t prove one causes the other'],
      },
      // # ─── Lesson 23: Reading Across Genres ───
      { id: 'b1-reading-across-genres', title: 'Reading Across Genres — Adapting Your Approach', description: 'Adjust your reading strategy when switching between different text types.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Match reading strategy to text genre', 'Adjust reading speed for different text types', 'Build a personal reading strategy toolkit'],
        sections: [
          { title: 'Genre Strategy Matrix', type: 'rule', content: 'NEWS ARTICLE: skim headline + first paragraph for the main story. Read on if interested. Speed: fast. FICTION/STORY: read carefully. Enjoy the language. Don\'t skip. Speed: moderate. TEXTBOOK: preview headings → read → review. Take notes. Speed: slow. EMAIL (work): scan for action items and deadlines. Speed: fast. CONTRACT/POLICY: read every word. Highlight key terms. Speed: very slow. BLOG/OPINION: skim for the main argument. Check if evidence-based. Speed: moderate. INSTRUCTIONS: read all steps before starting. Follow in order. Speed: slow. The worst mistake: reading everything at the same speed. Fast text + slow reading = wasted time. Important text + fast reading = missed details.' },
          { title: 'Building Reading Stamina', type: 'tip', content: 'At B1, you should aim for: 15-20 minutes of continuous reading without stopping. Understanding 80-90% of a text at your level without a dictionary. Reading 150-200 words per minute in English (native speakers read ~250 wpm). To build stamina: start with 10 minutes/day and add 2 minutes each week. Choose texts you ENJOY — motivation beats discipline. Re-read texts you liked — you notice more the second time. Mix genres — variety prevents boredom and builds flexibility. Track your progress — note how long you read and how much you understood.' },
          { title: 'Choose Your Strategy', type: 'exercise', question: 'You need to: (a) find out if a restaurant is open on Sundays, (b) understand a new company policy about remote work, (c) enjoy a short story before bed. What strategy for each?', answer: '(a) SCAN the restaurant website for opening hours. Look for "Sunday" or a timetable. Time: 30 seconds. (b) READ CAREFULLY the entire policy. Highlight action items. Note deadlines. Check what "must" vs "may" means for you. Time: 10-15 minutes. (c) READ FOR ENJOYMENT. No pressure, no notes, no speed targets. Enjoy the language and story. Time: as long as you want.', answerExplanation: 'Three completely different tasks, three completely different strategies. The key skill is making the right choice BEFORE you start reading. Scanning a company policy would miss important details. Carefully reading every word of a restaurant website would waste time. Strategy selection is what separates efficient readers from slow ones.' },
        ],
        keyTakeaways: ['Match strategy to genre: scan menus, skim news, read contracts carefully', 'Aim for 15-20 minutes of continuous reading at B1', 'The worst mistake is reading everything at the same speed'],
      },
      // # ─── Lesson 24: Vocabulary Building Through Reading ───
      { id: 'b1-reading-vocab-building', title: 'Vocabulary Building Through Reading', description: 'Learn new words naturally while reading — the most effective vocabulary strategy.',
        skill: 'reading', level: 'B1', duration: 10,
        objectives: ['Learn words in context rather than from lists', 'Use the "notice-guess-check-record" method', 'Build a personal vocabulary notebook from reading'],
        sections: [
          { title: 'The 4-Step Vocabulary Method', type: 'rule', content: 'Step 1: NOTICE — a word you don\'t know appears repeatedly or seems important. Step 2: GUESS — use context to guess the meaning. "The economy has been stagnant — no growth for three years." → stagnant probably means not growing / stuck. Step 3: CHECK — verify your guess with a dictionary (after reading, not during). Step 4: RECORD — write it down with: the word, the sentence you found it in, the definition, a personal example sentence. This method is 3x more effective than memorising word lists because you learn words IN CONTEXT, which helps your brain store and retrieve them.' },
          { title: 'What to Record', type: 'tip', content: 'For each new word, record: WORD: stagnant. PRONUNCIATION: /ˈstæɡ.nənt/. CONTEXT: "The economy has been stagnant." MEANING: not growing, not changing, stuck. MY SENTENCE: "My English was stagnant until I started reading every day." COLLOCATIONS: stagnant economy, stagnant water, stagnant wages. WORD FAMILY: stagnate (verb), stagnation (noun). Collocations are CRUCIAL — knowing "stagnant water" sounds natural but "stagnant person" sounds wrong is the difference between textbook English and natural English.' },
          { title: 'Practice the Method', type: 'exercise', question: '"The company faced unprecedented challenges during the pandemic. Supply chains were disrupted, customer demand plummeted, and many employees were furloughed." Use context to guess: (a) unprecedented, (b) plummeted, (c) furloughed.', answer: '(a) "Unprecedented" = never happened before. Clue: the pandemic was a new, unusual event causing new challenges. (b) "Plummeted" = fell sharply/dramatically. Clue: it\'s listed alongside other negative effects (disrupted, furloughed), so demand must have gone DOWN fast. (c) "Furloughed" = sent home from work temporarily (not fired, but not working). Clue: employees were affected but not "fired" or "laid off" — a different, softer word suggests temporary absence.', answerExplanation: 'Context gave you enough to guess all three correctly. "Unprecedented" = un (not) + precedented (happened before). "Plummeted" is surrounded by other negatives. "Furloughed" is used instead of "fired" — suggesting something less permanent. Now check a dictionary to confirm, then record these words with the sentences. This is how fluent readers build vocabulary — not from lists, but from real texts.' },
        ],
        keyTakeaways: ['Notice → Guess → Check → Record: learn words from reading, not lists', 'Record the CONTEXT sentence, not just the definition', 'Collocations (which words go together) are as important as definitions'],
      },
      // # ─── Lesson 25: B1 Reading Review ───
      { id: 'b1-reading-review', title: 'B1 Reading Review: Consolidation & Self-Assessment', description: 'Review all B1 reading skills and identify your strengths and areas for improvement.',
        skill: 'reading', level: 'B1', duration: 12,
        objectives: ['Apply all B1 reading strategies to a new text', 'Self-assess reading strengths and weaknesses', 'Set goals for B2 reading development'],
        sections: [
          { title: 'Your B1 Reading Skills', type: 'rule', content: 'At B1, you can now: ✓ Read articles of 300-500 words and find the thesis. ✓ Identify tone (positive, negative, neutral, sarcastic). ✓ Understand paragraph structure (topic sentence + support). ✓ Read opinion articles and evaluate arguments. ✓ Make inferences from context clues. ✓ Follow cause-effect chains and process descriptions. ✓ Summarise a text in your own words. ✓ Track pronouns and references across paragraphs. ✓ Read charts and describe data trends. ✓ Build vocabulary from reading context. ✓ Switch strategies by purpose and genre. These skills prepare you for B2, where you\'ll handle longer texts, more complex arguments, and academic writing.' },
          { title: 'Self-Assessment', type: 'tip', content: 'Rate yourself 1-5: Skimming for main ideas ___. Scanning for specific facts ___. Understanding opinion articles ___. Making inferences ___. Following cause-effect relationships ___. Summarising in your own words ___. Reading academic text introductions ___. Evaluating evidence quality ___. Tracking pronouns in long texts ___. Vocabulary building from reading ___. Scores of 4-5: strong. Keep practising. Scores of 2-3: review the specific lesson. Scores of 1: spend extra time on this skill. Your weakest area is where the biggest gains are — focus there.' },
          { title: 'Comprehensive Practice', type: 'exercise', question: '"Global tourism is recovering. The UN World Tourism Organisation reports that international arrivals reached 1.3 billion in 2025, just 5% below pre-pandemic levels. Southern Europe and Southeast Asia saw the strongest growth, driven by lower costs and favourable exchange rates. However, overtourism remains a concern. Barcelona and Venice have introduced visitor caps, and Bhutan charges tourists $200 per day. Critics argue these measures hurt local economies, but supporters say they protect residents\' quality of life." (a) What is the main idea? (b) Identify one fact and one opinion. (c) What is the tone?', answer: '(a) Main idea: Global tourism is recovering to near pre-pandemic levels, but overtourism is creating tension between economic benefits and local quality of life. (b) Fact: International arrivals reached 1.3 billion in 2025 (verifiable statistic from UNWTO). Opinion: critics who say measures "hurt local economies" and supporters who say they "protect quality of life" — both are value judgements. (c) Tone: neutral/balanced — the text presents both sides ("however," "critics argue... but supporters say") without taking a position.', answerExplanation: 'This exercise tests multiple B1 skills: main idea identification, fact vs opinion, and tone recognition. The text is balanced because it uses "however" to introduce the problem and presents both sides. A biased text would only show one perspective. Recognising balance is a key step toward B2 critical reading.' },
        ],
        keyTakeaways: ['B1 reading = longer texts, inference, evaluation, and strategy switching', 'Self-assess regularly — your weakest skill offers the biggest improvement opportunity', 'B2 next: longer texts, complex arguments, academic reading, and critical analysis'],
      },
    ],
  },
  {
    id: 'b2-reading',
    name: 'B2: Reading Skills',
    description: 'Read complex texts with confidence — academic articles, literary fiction, opinion pieces, and detailed reports.',
    icon: '📖',
    lessons: [
      // # ─── Lesson 1: Reading Complex Arguments ───
      { id: 'b2-reading-complex-arguments', title: 'Reading Complex Arguments', description: 'Follow multi-layered arguments with qualifications, concessions, and nuanced positions.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Track a thesis through multiple paragraphs', 'Understand qualifications and concessions', 'Map argument structure: claim → evidence → concession → rebuttal'],
        sections: [
          { title: 'Beyond Simple Arguments', type: 'rule', content: 'At B2, arguments are no longer black and white: QUALIFICATION: "This is generally true, ALTHOUGH there are exceptions." CONCESSION: "While opponents make a valid point about X, the evidence for Y is stronger." NUANCE: "The answer depends on context — in urban areas... but in rural areas..." HEDGING: "This may suggest..." "It could be argued that..." These make arguments more HONEST but harder to follow. The writer is NOT confused — they are acknowledging complexity. A B2 reader tracks the main claim through these qualifications without losing it.' },
          { title: 'Mapping Arguments', type: 'tip', content: 'Use this mental map while reading: CLAIM: what the writer believes. EVIDENCE: proof for the claim. CONCESSION: "Admittedly, the other side has a point about..." (the writer agrees with the opponent on ONE thing). REBUTTAL: "However, this does not undermine the main argument because..." (dismisses the concession). CONCLUSION: restates the claim, strengthened by having addressed the opposition. The concession is the hardest part — it looks like the writer is agreeing with the other side. But the rebuttal that follows shows it was a strategic move to appear fair-minded. Writers who concede AND rebut are more persuasive than those who ignore the other side.' },
          { title: 'Map This Argument', type: 'exercise', question: '"Universal basic income (UBI) deserves serious consideration. Pilot programmes in Finland and Kenya have shown improvements in wellbeing and entrepreneurship. Admittedly, the cost of a nationwide programme would be substantial — estimated at 5-10% of GDP. Nevertheless, when we account for savings from simplified welfare bureaucracy and reduced healthcare costs, the net expense is significantly lower than critics suggest."', answer: 'CLAIM: UBI deserves serious consideration. EVIDENCE: Pilot programmes in Finland and Kenya showed positive results (wellbeing, entrepreneurship). CONCESSION: "Admittedly" — the cost would be substantial (5-10% of GDP). The writer acknowledges this is a real concern. REBUTTAL: "Nevertheless" — savings from simplified welfare and reduced healthcare offset the cost. Net expense is lower than critics claim. Structure: The writer concedes the cost concern (showing fairness) then argues the NET cost is lower, making the concession less damaging to their overall argument.', answerExplanation: '"Admittedly" signals: "I agree with my opponents on this specific point." "Nevertheless" signals: "But that doesn\'t defeat my argument." This concede-and-rebut structure is the hallmark of sophisticated argumentation. A writer who ignores cost objections would be less convincing than one who acknowledges and addresses them.' },
        ],
        keyTakeaways: ['"Admittedly" / "Granted" = concession (agreeing with opponents on one point)', '"Nevertheless" / "Nonetheless" = rebuttal (but my main argument still holds)', 'Concession + rebuttal is STRONGER than ignoring the other side'],
      },
      // # ─── Lesson 2: Critical Reading — Evaluating Sources ───
      { id: 'b2-reading-evaluating-sources', title: 'Critical Reading — Evaluating Sources', description: 'Assess the reliability, bias, and quality of what you read.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Apply the CRAAP test (Currency, Relevance, Authority, Accuracy, Purpose)', 'Identify bias and vested interests', 'Rank sources by reliability'],
        sections: [
          { title: 'The CRAAP Test', type: 'rule', content: 'CURRENCY: when was it written? A 2015 article about AI is outdated. A 2025 article is current. RELEVANCE: does it address YOUR question? A general article about health may not help with a specific medical question. AUTHORITY: who wrote it? A professor of economics has more authority on trade policy than a lifestyle blogger. What are their credentials? ACCURACY: are claims supported by evidence? Are sources cited? Can you verify the data? PURPOSE: why was it written? To inform? To persuade? To sell something? To entertain? A pharmaceutical company\'s study of its own drug has an obvious purpose — profit. Not necessarily wrong, but worth scrutinising.' },
          { title: 'Source Hierarchy', type: 'tip', content: 'Most reliable → least reliable: Peer-reviewed journals (Nature, The Lancet) — reviewed by other experts. Government/official statistics (ONS, WHO, World Bank) — large datasets, methodology documented. Quality newspapers (reporting, not opinion columns) — fact-checked, editor-reviewed. Expert books — peer-reviewed by publishers, detailed arguments. Reputable news sites — BBC, Reuters, AP — fact-checking standards. Think tanks / NGOs — can be excellent but check for political leanings. Blogs and opinion sites — range from expert to uninformed. Social media — unverified, often emotional, echo-chamber effects. Anonymous forums — no accountability, no verification. This hierarchy is a guideline, not absolute — a bad journal article can be worse than a good blog post.' },
          { title: 'Evaluate This Source', type: 'exercise', question: 'You\'re writing an essay about whether coffee is healthy. You find: (A) A 2024 meta-analysis in The BMJ reviewing 40 studies with 1.2 million participants. (B) A blog post titled "10 Reasons Coffee Will Kill You" by a wellness influencer selling herbal tea. (C) A 2023 press release from Starbucks saying "Research confirms coffee\'s health benefits." Rank by reliability.', answer: '1. (A) BMJ meta-analysis — most reliable. Peer-reviewed journal, 40 studies combined, 1.2 million participants, recent (2024). 2. (C) Starbucks press release — has real research behind it but obvious bias (Starbucks profits from coffee being seen as healthy). Check which studies they cite. 3. (B) Blog post — least reliable. No credentials, selling a competing product (herbal tea = financial incentive to discredit coffee), sensationalised title. Use (A) as your primary source, verify (C)\'s claims, ignore (B).', answerExplanation: 'The BMJ is one of the world\'s top medical journals. A meta-analysis (combining many studies) is the strongest type of evidence. Starbucks has a financial interest — their press release is marketing disguised as information. The blog combines no credentials + financial bias (selling tea) + sensationalism. Critical reading means evaluating WHO is saying it and WHY, not just WHAT they say.' },
        ],
        keyTakeaways: ['CRAAP: Currency, Relevance, Authority, Accuracy, Purpose', 'Peer-reviewed journals > government data > quality news > blogs > social media', 'Always ask: "Who wrote this, and what do they gain from me believing it?"'],
      },
      // # ─── Lesson 3: Reading Between the Lines — Advanced Inference ───
      { id: 'b2-reading-advanced-inference', title: 'Advanced Inference — Subtext & Implication', description: 'Detect what sophisticated writers imply through word choice, structure, and omission.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Infer attitudes from subtle language choices', 'Understand implication through omission (what is NOT said)', 'Detect irony and understatement in formal writing'],
        sections: [
          { title: 'Subtle Inference Techniques', type: 'rule', content: 'WORD CHOICE: "The minister explained the policy" (neutral) vs "The minister defended the policy" (implies criticism exists) vs "The minister insisted the policy was working" (implies doubt). QUOTATION MARKS: "The company\'s \'eco-friendly\' packaging..." — scare quotes suggest the writer doubts the claim. PASSIVE VOICE for blame-avoidance: "Mistakes were made" (who made them?) vs "The CEO made mistakes" (clear responsibility). OMISSION: what the text DOESN\'T say can be as important as what it does. If a politician talks about achievements but doesn\'t mention the economy, the economy is probably bad. JUXTAPOSITION: placing two facts next to each other to imply a connection without stating it: "The CEO\'s bonus was $10 million. Meanwhile, 2,000 workers were laid off."' },
          { title: 'Understatement & Litotes', type: 'tip', content: 'British English especially uses understatement: "Not bad" = quite good. "Not entirely successful" = it failed. "There were some issues" = there were serious problems. "She wasn\'t best pleased" = she was furious. "It was a less than ideal outcome" = it was a disaster. Litotes (saying the negative of the opposite): "She\'s not unattractive" = she is attractive (but the speaker is being cautious). "This is no small achievement" = this is a very big achievement. Understatement makes critical comments sound polite — but the meaning is often harsh. Reading British academic writing, journalism, and professional emails requires understanding that "some concerns" might mean "grave doubts."' },
          { title: 'What Is Implied?', type: 'exercise', question: '"The company reported record profits this quarter. The CEO received a £4 million bonus. In an unrelated development, the company announced plans to close three factories, affecting 1,500 jobs. A spokesperson said the closures were \'necessary for long-term sustainability.\'"', answer: 'Implied: (1) The juxtaposition of "record profits" + "CEO bonus" + "factory closures" suggests the company is choosing shareholder/executive profits over workers. (2) "In an unrelated development" — the writer is being ironic. They clearly think it IS related. (3) "Necessary for long-term sustainability" in quotes — scare quotes suggest the writer doubts this justification. (4) The overall implication: the company is greedy — paying the CEO £4M while cutting 1,500 jobs, then claiming the closures are necessary.', answerExplanation: '"In an unrelated development" is the key phrase — by calling it "unrelated," the writer actually highlights the connection. This is a common journalistic technique: present facts side by side and let the reader draw the conclusion. The scare quotes around "necessary for long-term sustainability" signal that the writer views this as a PR excuse, not a genuine reason. None of this is stated — it\'s all implied.' },
        ],
        keyTakeaways: ['Juxtaposition (placing facts side by side) implies a connection without stating it', 'Scare quotes ("\'eco-friendly\'") signal the writer doubts the claim', '"In an unrelated development" often means the writer thinks it IS related — irony'],
      },
      // # ─── Lesson 4: Reading Academic Research Papers ───
      { id: 'b2-reading-research-papers', title: 'Reading Academic Research Papers', description: 'Navigate full research papers — abstract, methodology, results, and discussion.',
        skill: 'reading', level: 'B2', duration: 14,
        objectives: ['Read strategically: abstract → conclusion → introduction → methods', 'Evaluate methodology critically', 'Understand statistical significance and limitations'],
        sections: [
          { title: 'Strategic Reading Order', type: 'rule', content: 'Do NOT read a research paper from start to finish. Use this order: (1) TITLE + ABSTRACT: what was studied and what was found. (2) CONCLUSION: the main takeaway and implications. (3) INTRODUCTION: why the study was done and what gap it fills. (4) RESULTS: the actual findings and data. (5) METHODOLOGY: how the study was conducted (read this to evaluate reliability). (6) DISCUSSION: the authors\' interpretation (often speculative). This order prioritises WHAT they found before HOW they found it. Reading methodology first is inefficient — you don\'t know what you\'re evaluating yet.' },
          { title: 'Critical Questions for Research', type: 'tip', content: 'After reading, ask: SAMPLE: how many participants? 50 is weak, 5,000 is strong. Who are they? Students only ≠ the general population. METHODOLOGY: was it randomised? Controlled? Double-blind? (strongest design). CONFLICTS OF INTEREST: who funded the study? A study funded by Coca-Cola finding "sugar is harmless" should be viewed sceptically. REPLICATION: have other studies found the same thing? One study is a data point, not proof. EFFECT SIZE: "statistically significant" can mean a tiny real-world effect. A drug that reduces pain by 2% is "significant" but not meaningful. GENERALISABILITY: does the result apply beyond the study? A study on American college students may not apply in Japan.' },
          { title: 'Evaluate This Study', type: 'exercise', question: '"A study of 45 university students found that listening to classical music for 10 minutes before an exam improved test scores by an average of 3%. The study was conducted by the Classical Music Foundation and was not peer-reviewed." What are the strengths and weaknesses?', answer: 'Strengths: Specific measurement (3% improvement), controlled variable (10 minutes of music before exam). Weaknesses: (1) Tiny sample: 45 students is very small. (2) Non-representative: university students ≠ all people. (3) Conflict of interest: funded by the Classical Music Foundation — they benefit from positive results. (4) Not peer-reviewed: no expert scrutiny. (5) Small effect size: 3% may not be practically meaningful. (6) No control group mentioned: did they compare with silence? Other music? Conclusion: interesting but unreliable. Would need replication with larger, diverse samples, independent funding, and peer review.', answerExplanation: 'This study has multiple red flags: small sample, biased funder, no peer review, tiny effect. Any ONE weakness would require caution. All four together make this study essentially anecdotal. Critical reading of research means looking beyond "they found X" to "HOW did they find X and can we trust it?"' },
        ],
        keyTakeaways: ['Read papers in this order: abstract → conclusion → intro → results → methodology', 'Check: sample size, funding source, peer review status, effect size', 'One study is a data point, not proof — look for replication'],
      },
      // # ─── Lesson 5: Reading Literary Fiction ───
      { id: 'b2-reading-literary-fiction', title: 'Reading Literary Fiction', description: 'Engage with complex fiction — symbolism, unreliable narrators, and literary techniques.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Identify symbolism and metaphor in fiction', 'Recognise unreliable narrators', 'Understand how literary techniques create meaning'],
        sections: [
          { title: 'Literary Techniques', type: 'rule', content: 'SYMBOLISM: an object represents something bigger. A locked door = trapped / no escape. A sunrise = new beginning. Dark weather = sadness or danger. METAPHOR: comparing without "like/as." "Life is a journey." "The city was a jungle." FORESHADOWING: hints about what will happen later. "She didn\'t know it would be the last time she saw the house." IRONY: the opposite of what\'s expected. "The fire station burned down." UNRELIABLE NARRATOR: the person telling the story is biased, lying, or mistaken. You cannot trust everything they say. Clues: contradictions, other characters\' reactions, excessive self-justification.' },
          { title: 'Reading Beneath the Surface', type: 'tip', content: 'Literary fiction works on two levels: SURFACE: what literally happens (plot). DEPTH: what it means (theme, symbolism, commentary). Surface: "A man plants a garden in a war zone." Depth: hope persists even in destruction; life resists death; rebuilding starts small. Not every detail is symbolic — sometimes a door is just a door. But if the writer emphasises something, describes it in detail, or returns to it repeatedly, it probably carries deeper meaning. Ask: "Why did the writer choose THIS detail? What does it add beyond plot?"' },
          { title: 'Interpret This Passage', type: 'exercise', question: '"Every morning, the old man fed the birds in the park. He always sat on the same bench, scattering breadcrumbs in the same pattern. The pigeons knew him. One morning, the bench was empty. The birds waited. After an hour, they flew away."', answer: 'Surface: An old man who feeds birds one day doesn\'t come, and the birds leave. Depth: The empty bench symbolises death or absence. The routine (same bench, same pattern) represented stability and connection. The pigeons "knew him" = he mattered to something. The birds waiting = loyalty, then acceptance. "They flew away" = life continues. Theme: even the most faithful routines end; connections are real but temporary; absence is felt by those left behind. The writer never says the man died — the empty bench implies it.', answerExplanation: 'The passage never mentions death, yet most readers understand the man has died. This is inference through symbolism — the empty bench, the routine broken, the waiting birds. "They flew away" carries a quiet finality. Literary fiction trusts readers to understand what is implied. This is what makes it different from genre fiction, which would likely state "the old man had passed away the previous night."' },
        ],
        keyTakeaways: ['Literary fiction works on surface (plot) and depth (theme/symbolism)', 'If a writer emphasises a detail repeatedly, it probably carries deeper meaning', 'Unreliable narrators contradict themselves, over-justify, or are contradicted by other characters'],
      },
      // # ─── Lesson 6: Discourse Markers & Text Cohesion ───
      { id: 'b2-reading-discourse-markers', title: 'Discourse Markers & Text Cohesion', description: 'Understand how advanced connectors and discourse markers organise complex texts.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Recognise advanced discourse markers and their functions', 'Follow the logical flow of complex texts', 'Understand how cohesion devices hold paragraphs together'],
        sections: [
          { title: 'Advanced Discourse Markers', type: 'rule', content: 'ADDING: furthermore, moreover, in addition, not only... but also. CONTRASTING: nevertheless, nonetheless, on the contrary, conversely, that said. CONCEDING: admittedly, granted, while it is true that, to be fair. EMPHASISING: indeed, in fact, notably, significantly, crucially. CLARIFYING: in other words, that is to say, to put it simply, specifically. EXEMPLIFYING: for instance, namely, to illustrate, as evidenced by. CONCLUDING: in conclusion, to sum up, ultimately, all things considered. SEQUENCING: in the first place, subsequently, in the meantime, ultimately. Each marker tells you WHAT TYPE of information comes next — predicting this speeds up comprehension.' },
          { title: 'Cohesion Beyond Connectors', type: 'tip', content: 'Cohesion = how a text "sticks together." Beyond connectors: LEXICAL CHAINS: repeating related words: education → students → schools → teachers → curriculum → qualifications — all connected. SYNONYMS: using different words for the same thing: "the policy" → "this approach" → "the measure" → "the initiative." PARALLEL STRUCTURE: repeating grammatical patterns: "We need to invest in education, to strengthen healthcare, and to reform housing." ELLIPSIS: leaving out repeated words: "She likes coffee and [she likes] tea." These devices make text flow smoothly. Without them, writing feels choppy and disconnected.' },
          { title: 'Track the Cohesion', type: 'exercise', question: '"The government announced a new environmental policy. This ambitious initiative aims to reduce carbon emissions by 40% by 2030. Furthermore, the measure includes subsidies for electric vehicles. Nevertheless, critics argue that the scheme does not go far enough. Notably, the plan does not address industrial pollution, which accounts for 35% of total emissions."', answer: 'Cohesion devices: (1) "This ambitious initiative" = synonym chain for "new environmental policy." (2) "the measure" = another synonym. (3) "the scheme" = yet another synonym. (4) "the plan" = another synonym. Five different names for the same thing — avoids repetition while maintaining clarity. Discourse markers: "Furthermore" (adds another benefit), "Nevertheless" (introduces criticism), "Notably" (emphasises a specific gap). Flow: announcement → description → additional benefit → criticism → specific evidence for criticism.', answerExplanation: 'The text uses FIVE different terms for the same policy: policy → initiative → measure → scheme → plan. This is a standard academic/journalistic technique. If you don\'t track these synonyms, you might think the text is discussing five different things. Recognising synonym chains is essential for following complex texts at B2 and above.' },
        ],
        keyTakeaways: ['"Nevertheless" = but (strong). "Furthermore" = and also. "Notably" = pay attention to this.', 'Writers use synonym chains (policy → initiative → measure → scheme) to avoid repetition', 'Tracking these synonyms prevents confusion — they all refer to the SAME thing'],
      },
      // # ─── Lesson 7: Speed Reading Techniques ───
      { id: 'b2-reading-speed-reading', title: 'Speed Reading Techniques', description: 'Read faster without losing comprehension — essential for exams and professional work.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Increase reading speed from ~200 to ~280 wpm', 'Eliminate subvocalisation for scanning tasks', 'Use chunking to read phrases instead of individual words'],
        sections: [
          { title: 'Three Speed Techniques', type: 'rule', content: 'CHUNKING: read groups of 3-5 words together instead of one word at a time. Instead of: "The / scientist / discovered / a / new / species." Read: "The scientist discovered / a new species." Your eyes make fewer stops (fixations) per line, which increases speed. REDUCE REGRESSION: stop going back to re-read sentences. Trust your first pass. If you must re-read, do it AFTER finishing the paragraph, not mid-sentence. USE A POINTER: move your finger or a pen along the line. Your eyes follow the pointer, maintaining consistent speed and preventing regression. These three techniques alone can increase reading speed by 30-50%.' },
          { title: 'When NOT to Speed Read', type: 'tip', content: 'Speed reading works for: news articles, emails, reports, textbook reviews, familiar topics. Speed reading does NOT work for: legal contracts (every word matters), poetry (rhythm and sound matter), instructions (sequence matters), unfamiliar topics (you need to process new concepts), literary fiction (nuance and style matter). The goal is NOT to read everything fast — it\'s to read at the RIGHT speed for the RIGHT text. A flexible reader has 3-4 speeds: scanning (600+ wpm), skimming (400 wpm), normal reading (250 wpm), careful study (150 wpm).' },
          { title: 'Practice Chunking', type: 'exercise', question: 'Read this passage by chunking (3-5 words per fixation): "The global economy / is expected to grow / by 3.2% in 2026 / according to the IMF. / Emerging markets / will lead the recovery / with growth rates / of 4-5% / while advanced economies / will see modest growth / of around 2%." How many fixations did you use? What are the two key facts?', answer: 'The passage has about 11 natural chunks (shown by the / marks). With chunking, you made approximately 11 fixations instead of 35+ individual word fixations. Key facts: (1) Global economy expected to grow 3.2% in 2026 (IMF). (2) Emerging markets: 4-5% growth. Advanced economies: ~2% growth. Chunking tripled your reading speed for this passage while maintaining comprehension of the key data.', answerExplanation: 'Chunking works because your brain can process 3-5 words simultaneously — you don\'t need to read each word individually. The "/" marks show natural phrase boundaries. With practice, you chunk automatically without needing markers. Start with short texts and gradually apply chunking to longer ones.' },
        ],
        keyTakeaways: ['Chunking (reading 3-5 words at once) can increase speed by 30-50%', 'Use a finger/pointer to maintain consistent speed and reduce regression', 'Speed reading is for articles and reports, NOT for contracts, poetry, or instructions'],
      },
      // # ─── Lesson 8: Reading Across Perspectives ───
      { id: 'b2-reading-across-perspectives', title: 'Reading Across Perspectives', description: 'Read texts from opposing viewpoints and synthesise a balanced understanding.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Identify the perspective and bias of each source', 'Find common ground between opposing views', 'Form your own evidence-based position'],
        sections: [
          { title: 'Perspective Awareness', type: 'rule', content: 'Every text has a perspective — the viewpoint from which it is written. Perspective is shaped by: the writer\'s background, profession, and values. the publisher\'s editorial stance. the intended audience. the cultural context. Example — "New housing development approved": Residents: "Our neighbourhood is being destroyed." Developer: "We\'re creating homes for 500 families." Council: "This balances housing needs with community concerns." Environmental group: "Green space is being sacrificed for profit." Same event, four different stories. None is "wrong" — each sees different aspects of the same reality.' },
          { title: 'Synthesis — Beyond "Both Sides"', type: 'tip', content: 'Synthesis ≠ "Person A says X, Person B says Y." Synthesis = finding the deeper truth that accounts for BOTH perspectives. Steps: (1) Read Position A. Note the strongest argument. (2) Read Position B. Note the strongest argument. (3) Find where they AGREE (common ground). (4) Identify where they DISAGREE and WHY (values? data? definitions?). (5) Form YOUR position based on the strongest evidence from both sides. Example synthesis: "Both sides agree housing is needed. The dispute is whether this location is appropriate, given the environmental cost. A compromise — reduced density with green space preservation — might address both concerns."' },
          { title: 'Synthesise These Perspectives', type: 'exercise', question: 'Perspective A: "Social media is harmful to teenagers. Studies show increased rates of anxiety, depression, and cyberbullying. Parents should limit screen time." Perspective B: "Social media helps teenagers develop social skills, access support communities, and express their identity. Banning it is counterproductive."', answer: 'Common ground: Both agree social media has significant impact on teenagers. Disagreement: A focuses on harms (mental health, bullying). B focuses on benefits (social skills, community, identity). Synthesis: Social media offers genuine benefits for teen development but also carries real risks. The answer is not a ban or unrestricted access — it is guided use: teaching digital literacy, setting boundaries together, and monitoring for warning signs while allowing teens to benefit from connection and self-expression. The key variable is HOW it is used, not WHETHER it is used.', answerExplanation: 'Neither perspective is completely right or wrong. Synthesis acknowledges that BOTH contain valid points and identifies the REAL question (how to use it wisely) rather than the false binary (ban vs unrestricted access). This is the thinking skill that B2+ reading builds — moving beyond "who is right?" to "what is the most complete understanding?"' },
        ],
        keyTakeaways: ['Every text has a perspective — identify it before accepting the argument', 'Synthesis ≠ listing both sides. Synthesis = finding the deeper truth that accounts for both.', 'The real question is often not "who is right?" but "what are they actually disagreeing about?"'],
      },
      // # ─── Lesson 9: Reading Satire & Commentary ───
      { id: 'b2-reading-satire', title: 'Reading Satire & Social Commentary', description: 'Understand texts that use humour, exaggeration, and irony to criticise society.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Recognise satire and distinguish it from serious writing', 'Understand the target of satirical criticism', 'Appreciate how exaggeration reveals truth'],
        sections: [
          { title: 'How Satire Works', type: 'rule', content: 'Satire uses humour to criticise. Key techniques: EXAGGERATION: making something bigger to show how absurd it is. "The committee spent 6 months and £50,000 deciding the colour of the new office carpet." IRONY: saying the opposite of what you mean. "What a brilliant idea to build a car park on the nature reserve." PARODY: imitating something to mock it. A fake corporate memo full of meaningless jargon. ABSURDISM: taking something to its logical extreme. "If we charge for everything, why not charge employees for breathing office air?" The TARGET is what the writer is actually criticising — not what they seem to be discussing on the surface.' },
          { title: 'Finding the Target', type: 'tip', content: 'Satire is never really about what it appears to be about: A story about animals ruling a farm → criticises totalitarian government (Orwell). An article praising a terrible product → criticises consumer culture. A mock-serious report on office life → criticises corporate bureaucracy. To find the target: (1) What is being exaggerated? (2) Who or what looks ridiculous? (3) What real-world issue does this parallel? (4) If you removed the humour, what would the serious complaint be? Satire that needs explaining often fails — the best satire makes you laugh AND think simultaneously.' },
          { title: 'What Is Being Criticised?', type: 'exercise', question: '"The Productivity Institute is delighted to announce that after 18 months of intensive study, focus groups, stakeholder consultations, and a preliminary report on the preliminary report, we have successfully produced a 200-page document entitled \'How to Be More Efficient.\' We are now forming a committee to discuss how to implement the recommendations. The committee will report in 2028."', answer: 'Target: bureaucratic inefficiency and self-defeating organisations. The satire shows: (1) 18 months for something that should take days — exaggeration of slowness. (2) "A preliminary report on the preliminary report" — absurd levels of process. (3) An efficiency institute that is itself wildly inefficient — irony. (4) "Report in 2028" — the problem will never actually be solved. The real criticism: some organisations are so focused on process that they never achieve outcomes. The very thing designed to fix inefficiency has become the source of it.', answerExplanation: 'The humour comes from the GAP between what the organisation claims to do (improve efficiency) and what it actually does (waste time on reports about reports). This is dramatic irony — the reader sees what the fictional institution cannot. Satire works because it reveals truth through laughter — we recognise real bureaucracies in this exaggeration.' },
        ],
        keyTakeaways: ['Satire uses exaggeration, irony, and absurdism to criticise real issues', 'The TARGET is never what the text appears to discuss on the surface', 'Ask: "If I removed the humour, what is the serious complaint?"'],
      },
      // # ─── Lesson 10: Reading Long-Form Journalism ───
      { id: 'b2-reading-longform', title: 'Reading Long-Form Journalism', description: 'Engage with 2,000+ word articles that combine reporting, narrative, and analysis.',
        skill: 'reading', level: 'B2', duration: 14,
        objectives: ['Maintain focus through extended reading', 'Distinguish between reported facts, quoted opinions, and journalist analysis', 'Identify the narrative arc of investigative pieces'],
        sections: [
          { title: 'Long-Form Structure', type: 'rule', content: 'Long-form journalism (2,000-10,000 words) uses a different structure from news: OPENING SCENE: a vivid, specific moment that hooks you. "At 3 AM, Maria\'s phone rang..." CONTEXT: zooms out to the bigger picture. "She was one of 50,000 nurses working through the crisis." NUT GRAPH: the paragraph that explains WHY this story matters (usually paragraphs 3-5). NARRATIVE THREAD: the story weaves between the personal (Maria) and the systemic (the healthcare crisis). EXPERT VOICES: quotes from analysts, researchers, officials — providing authority. KICKER: the final scene or quote that leaves a lasting impression, often circling back to the opening.' },
          { title: 'Staying Focused', type: 'tip', content: 'Long-form reading strategies: PREVIEW: read the first 3 paragraphs and the last paragraph. This gives you the hook and the conclusion. CHUNK: break the article into 500-word sections. Read one section, pause, summarise in one sentence. TRACK THE THREAD: who is the central character? What is their journey? Follow them through the article. SEPARATE LAYERS: personal story (narrative) vs expert analysis (data/quotes) vs journalist\'s framing (editorial). TAKE BREAKS: reading 2,000+ words takes 10-15 minutes. It\'s OK to pause. Set the article aside and return to it. The best long-form articles reward careful reading — they are designed to be consumed slowly.' },
          { title: 'Identify the Layers', type: 'exercise', question: '"James lost his job at the factory in March. [Paragraph about his personal experience.] According to the Office for National Statistics, manufacturing employment fell by 12% in the region. [Data paragraph.] \'The economic model has fundamentally shifted,\' says Professor Lee of the London School of Economics. [Expert quote.] The government\'s response has been slow and, critics argue, inadequate. [Journalist analysis.]" Label each layer.', answer: 'Layer 1 — PERSONAL NARRATIVE: James\'s story. Puts a human face on the issue. Makes the reader care. Layer 2 — DATA/EVIDENCE: ONS statistic (12% fall). Proves this is not just one person\'s problem. Layer 3 — EXPERT ANALYSIS: Professor Lee. Provides intellectual framework ("fundamentally shifted"). Layer 4 — JOURNALIST FRAMING: "slow and... inadequate." The journalist\'s own editorial assessment (note "critics argue" provides cover). These four layers work together: personal story hooks you, data proves it\'s systemic, experts explain why, journalist evaluates the response.', answerExplanation: 'Recognising these layers prevents confusion. When you read "the response has been inadequate," you know this is the JOURNALIST\'S framing, not a proven fact. When you read James\'s story, you know this is ONE person\'s experience, not representative of everyone. Each layer serves a different purpose, and understanding this makes you a more critical reader of long-form journalism.' },
        ],
        keyTakeaways: ['Long-form articles weave personal narrative + data + expert quotes + journalist analysis', 'Preview the first 3 and last paragraphs before diving in', 'Track which layer you\'re reading — personal story, data, expert, or journalist opinion'],
      },
      // # ─── Lesson 11: Rhetorical Analysis ───
      { id: 'b2-reading-rhetorical-analysis', title: 'Rhetorical Analysis — How Writers Persuade', description: 'Analyse the persuasive strategies writers use — ethos, pathos, and logos.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Identify ethos (credibility), pathos (emotion), and logos (logic)', 'Evaluate which rhetorical strategy dominates a text', 'Recognise when rhetoric is used to manipulate rather than inform'],
        sections: [
          { title: 'The Three Appeals', type: 'rule', content: 'ETHOS (credibility): the writer establishes trust through expertise, credentials, or shared values. "As a doctor with 20 years\' experience..." "Leading universities agree..." PATHOS (emotion): the writer appeals to your feelings — fear, sympathy, anger, hope. "Imagine a child going to bed hungry tonight." "Think about what this means for YOUR family." LOGOS (logic): the writer uses evidence, data, and reasoning. "Studies show that X leads to Y." "If we accept A, then logically B must follow." Most persuasive texts use ALL THREE — but one usually dominates. Political speeches: heavy pathos. Scientific papers: heavy logos. Expert opinion pieces: heavy ethos.' },
          { title: 'Rhetoric vs Manipulation', type: 'tip', content: 'Rhetoric is persuasion — it can be honest or dishonest. Warning signs of manipulation: EMOTIONAL MANIPULATION: making you feel guilty/afraid to prevent rational analysis. "If you don\'t support this, you don\'t care about children." FALSE AUTHORITY: citing irrelevant credentials. A celebrity endorsing a medical product. LOGICAL FALLACIES: flawed reasoning presented as sound. "Everyone agrees, so it must be true" (appeal to popularity). URGENCY PRESSURE: "Act now before it\'s too late!" (prevents careful thinking). Honest rhetoric: uses all three appeals, presents evidence fairly, acknowledges counter-arguments, gives you time to think. Dishonest rhetoric: relies heavily on one appeal (usually pathos), cherry-picks evidence, ignores opposition, pressures immediate action.' },
          { title: 'Analyse the Rhetoric', type: 'exercise', question: '"As a mother of three, I know the value of safety. Our neighbourhood has seen a 40% increase in traffic accidents since the speed limit was raised. Last month, 8-year-old Emma was hit crossing the street outside her school. She spent two weeks in hospital. The council must reinstate the lower speed limit before another child is hurt."', answer: 'ETHOS: "As a mother of three" — establishes credibility as a parent who understands child safety. LOGOS: "40% increase in traffic accidents" — statistical evidence supporting her claim. PATHOS: Emma\'s story — a specific child, age given, hospitalised — designed to make readers feel sympathy and fear. The dominant appeal is PATHOS — Emma\'s story carries the emotional weight. The statistic (logos) supports but doesn\'t drive the argument. The conclusion ("before another child is hurt") uses fear to demand action. Is it manipulative? Arguably not — the statistic is real, the personal story is relevant. But the strong emotional framing could prevent readers from considering whether other factors (road design, school crossing patrols) might be more effective than a speed limit change.', answerExplanation: 'This text uses all three appeals effectively. The ethos establishes standing, the logos provides evidence, and the pathos makes it personal. The key question is whether the emotional appeal overwhelms critical thinking. A reader swayed only by Emma\'s story might not ask: "What else caused the increase? Would the speed change alone fix it?" Rhetorical analysis helps you feel the emotions AND think critically at the same time.' },
        ],
        keyTakeaways: ['Ethos = credibility, Pathos = emotion, Logos = logic — most texts use all three', 'The dominant appeal reveals the writer\'s strategy', 'Honest rhetoric combines appeals and gives you time to think; manipulation pressures with one appeal'],
      },
      // # ─── Lesson 12: Reading Across Cultures ───
      { id: 'b2-reading-across-cultures', title: 'Reading Across Cultures', description: 'Understand how cultural context affects meaning, assumptions, and communication styles in texts.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Recognise culturally-specific references and assumptions', 'Understand direct vs indirect communication in writing', 'Read texts from outside your cultural context with awareness'],
        sections: [
          { title: 'Cultural Assumptions in Texts', type: 'rule', content: 'Every text carries cultural assumptions: WESTERN assumption: the individual is the primary unit. "Follow your dreams." "Be yourself." COLLECTIVIST assumption: the group comes first. "Consider your family." "Duty before desire." DIRECT cultures (US, Germany, Netherlands): say exactly what they mean. "This proposal is not good enough." INDIRECT cultures (UK, Japan, Thailand): communicate through implication. UK: "This is quite interesting" = it is not interesting. "With respect" = I completely disagree. Japan: "That would be difficult" = no. Understanding these differences prevents misreading texts from other cultures.' },
          { title: 'British Indirectness', type: 'tip', content: 'British English is famously indirect. A guide: "I hear what you say" = I disagree and will ignore you. "With the greatest respect" = I think you are wrong. "That\'s a very brave proposal" = you are insane. "Quite good" = disappointing. "Very interesting" = I don\'t like it. "I\'ll bear it in mind" = I will do nothing. "Perhaps you could consider..." = do this immediately. "It\'s fine" = it is not fine. This is NOT sarcasm — it is a genuine cultural communication style. If you read British business emails, academic reviews, or diplomatic language literally, you will misunderstand the message entirely.' },
          { title: 'Decode This Feedback', type: 'exercise', question: 'A British professor writes: "This essay shows some promising ideas, though there is scope for development in places. The argument might benefit from additional evidence, and I wonder if the conclusion fully reflects the complexity of the issue. You may wish to revisit the structure." What does this actually mean?', answer: 'Decoded: "Some promising ideas" = a few things are OK, but most of the essay is weak. "Scope for development" = significant improvement needed. "Might benefit from additional evidence" = your argument is not supported — add evidence (this is an instruction, not a suggestion). "I wonder if the conclusion fully reflects the complexity" = your conclusion is simplistic and possibly wrong. "You may wish to revisit the structure" = the structure is poor — reorganise it. Overall: this is quite negative feedback delivered politely. The essay needs major revision. Every "might," "perhaps," "you may wish to" is a polite instruction, not an optional suggestion.', answerExplanation: 'British academic feedback uses hedging to soften criticism. "You may wish to" is not a casual suggestion — it is a directive. "Scope for development" is not gentle encouragement — it means the work is insufficient. Reading this literally ("some promising ideas" sounds positive!) would cause the student to think the essay was nearly good enough, when it actually needs substantial rework. Cultural reading skills prevent this misinterpretation.' },
        ],
        keyTakeaways: ['British "quite good" ≈ disappointing. British "you may wish to" ≈ you must.', 'Every text carries cultural assumptions about individualism, directness, and hierarchy', 'If a text seems surprisingly mild or vague, check if the culture uses indirect communication'],
      },
      // # ─── Lesson 13: Synthesising Multiple Sources ───
      { id: 'b2-reading-synthesis', title: 'Synthesising Multiple Sources', description: 'Combine information from 3+ sources into a coherent understanding — essential for research and exams.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Organise information from multiple sources by theme', 'Identify agreements, disagreements, and gaps across sources', 'Write a synthesis paragraph from multiple readings'],
        sections: [
          { title: 'Synthesis vs Summary', type: 'rule', content: 'SUMMARY (per source): Source A says X. Source B says Y. Source C says Z. (Three separate mini-reports.) SYNTHESIS (across sources): "All three sources agree on X. However, A and B disagree about Y — A argues... while B contends... C introduces a third perspective by suggesting Z, which partially resolves the disagreement." Synthesis WEAVES sources together by THEME, not by source. Structure your synthesis around IDEAS, not around "Source A says... Source B says..."' },
          { title: 'The Synthesis Matrix', type: 'tip', content: 'Create a mental (or physical) grid: THEME | Source A | Source B | Source C. Causes: ... | ... | ... Effects: ... | ... | ... Solutions: ... | ... | ... Fill in each cell with what each source says about each theme. Look for: AGREEMENT: "All three sources identify X as a major cause." DISAGREEMENT: "While A blames individuals, B and C point to systemic factors." GAPS: "None of the sources address the long-term consequences." UNIQUE CONTRIBUTIONS: "Only Source C discusses the economic implications." This matrix reveals patterns you cannot see by reading sources one at a time.' },
          { title: 'Synthesise These Three Sources', type: 'exercise', question: 'Source A (WHO report): "Air pollution causes 7 million premature deaths annually. The main sources are transport, industry, and household cooking." Source B (Economics journal): "The economic cost of air pollution is estimated at $5 trillion annually, including healthcare and lost productivity." Source C (Environmental NGO): "Current government policies are insufficient. Only 12 countries meet WHO air quality guidelines."', answer: 'Synthesis: Air pollution is a global crisis with devastating health, economic, and policy dimensions. WHO data links pollution to 7 million premature deaths annually, while economic analysis estimates the cost at $5 trillion — demonstrating that the problem is not only a health emergency but also a massive economic burden. Despite this, government action remains inadequate: only 12 of the world\'s nations meet WHO air quality standards. The main pollution sources — transport, industry, and household cooking — require both technological solutions and policy enforcement, suggesting that current approaches fail because they address individual sources without systemic coordination.', answerExplanation: 'This synthesis weaves all three sources by theme (scale → cost → policy failure) rather than listing them separately. It adds a concluding insight ("current approaches fail because...") that no single source provides — this is the value of synthesis. The synthesis is more than the sum of its parts.' },
        ],
        keyTakeaways: ['Synthesis weaves sources by THEME, not by source ("Source A says... Source B says...")','Use a synthesis matrix: themes in rows, sources in columns', 'The best synthesis adds insight that no single source provides alone'],
      },
      // # ─── Lesson 14: Reading Data & Visualisations ───
      { id: 'b2-reading-data-visuals', title: 'Reading Data & Visualisations', description: 'Interpret charts, graphs, tables, and infographics embedded in written texts.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Read bar charts, line graphs, and pie charts accurately', 'Connect data visualisations to the surrounding text', 'Identify when data is presented misleadingly'],
        sections: [
          { title: 'Common Data Formats', type: 'rule', content: 'BAR CHARTS: compare quantities. "Country A exports twice as much as Country B." Read: title, axis labels, scale, and units. LINE GRAPHS: show change over time. "Sales rose sharply between March and June." Read: the trend (up/down/flat), the steepness, and any sudden changes. PIE CHARTS: show proportions of a whole. "Transport accounts for 29% of emissions." Read: the largest and smallest slices, and what the whole represents. TABLES: precise numbers in rows and columns. Read: column headers first, then scan for patterns, extremes, and outliers. Always read the TITLE and LABELS first — a graph without context is meaningless.' },
          { title: 'Misleading Data', type: 'tip', content: 'Data can be presented honestly or misleadingly: TRUNCATED Y-AXIS: a bar chart that starts at 95 instead of 0 makes a 2% difference look enormous. Always check where the axis starts. CHERRY-PICKED TIME FRAME: "Sales grew 300% this quarter!" — but they crashed 90% last quarter. The full picture tells a different story. MISSING CONTEXT: "50,000 people signed the petition!" — but out of a population of 67 million, that is 0.07%. NO UNITS: "Pollution increased by 15" — 15 what? Parts per million? Percent? Tonnes? CORRELATION PRESENTED AS CAUSATION: "Ice cream sales and drowning both increase in summer" — ice cream doesn\'t cause drowning. Both increase because of hot weather.' },
          { title: 'Read This Data', type: 'exercise', question: 'A bar chart shows "Customer Satisfaction" for three companies: Company A: 92%, Company B: 89%, Company C: 88%. The Y-axis starts at 85%. The article says: "Company A dramatically outperforms its rivals in customer satisfaction." Is this accurate?', answer: 'No — this is misleading. The Y-axis starts at 85%, making a 4% difference (88-92%) look like a massive gap. If the Y-axis started at 0%, all three bars would appear nearly identical — tall bars of almost equal height. The word "dramatically" is not supported by the data. A 4-percentage-point difference may or may not be statistically significant depending on sample size and margin of error (neither of which are provided). Accurate description: "Company A leads by a small margin in customer satisfaction (92% vs 88-89%)." The visual presentation and the language both exaggerate a minor difference.', answerExplanation: 'Truncated axes are the most common form of misleading data visualisation. Always check: (1) Where does the axis start? (2) What is the actual numerical difference? (3) Does the language match the data, or does it exaggerate? At B2, you read the DATA, not just the VISUAL. The chart was designed to make 4% look dramatic — your job is to see through that.' },
        ],
        keyTakeaways: ['Always read chart titles, axis labels, and units before interpreting', 'Truncated Y-axes exaggerate small differences — check where the axis starts', '"Dramatic" and "significant" should be supported by actual numbers, not visual tricks'],
      },
      // # ─── Lesson 15: Fact vs Opinion in Complex Texts ───
      { id: 'b2-reading-fact-opinion', title: 'Fact vs Opinion in Complex Texts', description: 'Distinguish verifiable facts from opinions in texts where they are deliberately blended.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Identify factual claims vs value judgements', 'Recognise opinion disguised as fact', 'Evaluate mixed fact-opinion statements'],
        sections: [
          { title: 'Fact vs Opinion', type: 'rule', content: 'FACT: can be verified or disproven. "The UK population is 67 million." "Water boils at 100°C at sea level." "The company reported £4.2 billion in revenue." OPINION: a judgement, belief, or interpretation. "The UK is overcrowded." "Coffee tastes better than tea." "The company\'s revenue growth was impressive." MIXED (fact + opinion): "The company\'s impressive £4.2 billion revenue..." — the revenue is a fact, but "impressive" is the writer\'s opinion. Key words that signal opinion: should, must, best, worst, clearly, obviously, arguably, unacceptable, brilliant, disgraceful, essential. Facts use numbers, dates, named sources. Opinions use adjectives, comparisons, and value judgements.' },
          { title: 'Opinion Disguised as Fact', type: 'tip', content: 'Watch for opinions dressed up as facts: "Everyone knows that..." — no, not everyone. This is an opinion with social pressure. "It is clear that..." — clear to whom? This is the writer asserting an opinion as obvious. "The only solution is..." — there are almost always multiple solutions. "Studies show..." (without naming the study) — vague authority for what may be an opinion. "Common sense suggests..." — common sense is cultural, not universal. At B2, the challenge is that professional writers are SKILLED at blending fact and opinion. They embed opinions inside factual sentences so you absorb the opinion without questioning it. Your job is to separate them.' },
          { title: 'Separate Fact from Opinion', type: 'exercise', question: '"The government\'s reckless decision to cut education funding by 8% will inevitably lead to a generation of under-educated citizens who cannot compete in the global economy."', answer: 'FACT: education funding was cut by 8% — this is verifiable. OPINION 1: "reckless" — a value judgement. Another person might call it "necessary" or "pragmatic." OPINION 2: "inevitably" — this presents a prediction as certain. The outcome is unknown. OPINION 3: "under-educated" — assumes the cuts will reduce education quality. This is plausible but not proven. OPINION 4: "cannot compete" — another prediction stated as certain. The sentence contains ONE fact surrounded by FOUR opinions. A factual version: "The government cut education funding by 8%. Critics argue this could reduce educational quality, potentially affecting future competitiveness." Same information, but facts and opinions are separated.', answerExplanation: 'The original sentence is designed to feel like a statement of fact — it reads confidently and uses a real number (8%). But the number is the only verifiable part. Everything else is the writer\'s prediction and judgement. At B2, you identify WHERE the fact ends and the opinion begins — even when the writer deliberately blurs the boundary.' },
        ],
        keyTakeaways: ['Facts can be verified. Opinions contain judgements (should, best, reckless, impressive).', '"Everyone knows," "it is clear," and "the only solution" are opinions disguised as facts', 'Professional writers embed opinions inside factual sentences — learn to separate them'],
      },
      // # ─── Lesson 16: Reading Contracts & Legal Language ───
      { id: 'b2-reading-legal-language', title: 'Reading Contracts & Legal Language', description: 'Understand the formal, precise language used in contracts, terms of service, and official documents.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Decode common legal phrases and structures', 'Identify key clauses in contracts', 'Understand the practical implications of legal language'],
        sections: [
          { title: 'Legal Language Basics', type: 'rule', content: 'Legal English uses specific conventions: "SHALL" = must (an obligation). "The tenant shall pay rent on the first of each month." "MAY" = is allowed to (permission). "The landlord may enter with 24 hours\' notice." "NOTWITHSTANDING" = despite / regardless of. "Notwithstanding clause 3, the company reserves the right to..." "HEREIN" / "HEREINAFTER" = in this document / from this point forward. "The company (hereinafter \'the Provider\')..." "IN LIEU OF" = instead of. "Payment in lieu of notice." "SUBJECT TO" = depending on / conditional upon. "Subject to approval by the board." "INDEMNIFY" = compensate for loss or damage. "The client shall indemnify the provider against all claims."' },
          { title: 'Reading Terms of Service', type: 'tip', content: 'Key sections to find in any Terms of Service: DATA USE: "We collect... We share... We may sell..." — what happens to YOUR information? TERMINATION: how can they end your account? Can they do it without warning? LIABILITY: "We are not responsible for..." — what happens if something goes wrong? CHANGES: "We reserve the right to modify these terms at any time." — this means the contract can change without your agreement. AUTO-RENEWAL: "Your subscription will automatically renew..." — charges continue unless YOU cancel. JURISDICTION: "These terms are governed by the laws of [country/state]." — this determines where disputes are resolved. Most people never read these. At B2, you should be able to skim for the key sections that affect your rights and money.' },
          { title: 'Decode This Clause', type: 'exercise', question: '"The Company shall not be liable for any indirect, incidental, special, consequential, or punitive damages, including without limitation, loss of profits, data, use, goodwill, or other intangible losses, resulting from your access to or use of or inability to access or use the Service."', answer: 'Decoded: the company is NOT responsible for: (1) "indirect damages" — problems caused as a RESULT of their service failing (e.g., you lost a client because their platform was down). (2) "loss of profits" — if their service breaks and you lose money, they won\'t compensate you. (3) "loss of data" — if your data disappears, they are not liable. (4) "inability to access or use" — if the service goes offline, they owe you nothing. (5) "other intangible losses" — anything else you might claim. In plain English: "If our service breaks, crashes, loses your data, or goes offline, we are not responsible for any consequences. You cannot sue us for damages." This is standard in tech ToS — and it means you should always back up your data independently.', answerExplanation: 'This clause is deliberately comprehensive — it lists EVERY type of damage to ensure maximum legal protection for the company. Understanding these clauses helps you make informed decisions: if a service disclaims liability for data loss, you know that backing up your data is YOUR responsibility. B2 legal reading is practical — you don\'t need to be a lawyer, but you do need to understand what you\'re agreeing to.' },
        ],
        keyTakeaways: ['"Shall" = must. "May" = is allowed to. "Notwithstanding" = despite.', 'In Terms of Service, always find: data use, termination, liability, auto-renewal, and changes clauses', 'Liability disclaimers mean the company is NOT responsible — back up your data and read before signing'],
      },
      // # ─── Lesson 17: Paraphrasing & Restating Ideas ───
      { id: 'b2-reading-paraphrasing', title: 'Paraphrasing & Restating Ideas', description: 'Restate what you read in your own words — a core academic and professional skill.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Paraphrase sentences without changing meaning', 'Avoid plagiarism by restating with different structure AND vocabulary', 'Distinguish between effective and poor paraphrasing'],
        sections: [
          { title: 'What Makes a Good Paraphrase?', type: 'rule', content: 'A good paraphrase changes BOTH vocabulary AND sentence structure while keeping the meaning: ORIGINAL: "Climate change is the greatest threat facing humanity in the 21st century." BAD paraphrase (too similar): "Climate change is the biggest threat facing humans in the 21st century." (Only changed two words.) GOOD paraphrase: "The most significant challenge of our era is the changing global climate." (Different structure, different vocabulary, same meaning.) STEPS: (1) Read the original. (2) Close the text. (3) Write the idea in YOUR words from memory. (4) Check: does it mean the same thing? (5) Check: is the language different enough? If you can recite the original while writing, you\'re copying, not paraphrasing.' },
          { title: 'Paraphrase Techniques', type: 'tip', content: 'Change STRUCTURE: "X causes Y" → "Y is a result of X" → "Y occurs because of X." Change VOICE: "Scientists discovered X" → "X was discovered by scientists." Change WORD CLASS: "the discovery of penicillin" (noun) → "when penicillin was discovered" (verb). Use SYNONYMS: greatest → most significant. Threat → challenge/risk/danger. Facing → confronting. Combine sentences or split them. Move clauses to different positions. Keep TECHNICAL TERMS unchanged — "photosynthesis" cannot be paraphrased. Keep PROPER NOUNS unchanged — "the United Nations" stays the same. The goal is to demonstrate UNDERSTANDING, not just word-swapping.' },
          { title: 'Paraphrase This', type: 'exercise', question: 'Original: "Research suggests that bilingual children develop stronger problem-solving abilities than their monolingual peers, possibly because managing two language systems enhances cognitive flexibility."', answer: 'Good paraphrase: "Children who speak two languages may develop better problem-solving skills than those who speak one, potentially because the cognitive demands of switching between languages increase mental adaptability." Changes made: "bilingual" → "who speak two languages" (definition instead of term). "Stronger" → "better." "Monolingual peers" → "those who speak one." "Managing two language systems" → "the cognitive demands of switching between languages." "Enhances cognitive flexibility" → "increase mental adaptability." Structure changed: the "possibly because" clause is restructured with "potentially because." The hedging ("suggests," "possibly") is preserved as "may" and "potentially" — removing the hedging would change the meaning.', answerExplanation: 'Notice that the paraphrase preserves the HEDGING — "suggests" and "possibly" become "may" and "potentially." A paraphrase that changed "suggests" to "proves" would change the meaning, which is worse than copying the words. Paraphrasing tests comprehension: if you truly understand an idea, you can express it differently. If you can only copy the original, you may not fully understand it.' },
        ],
        keyTakeaways: ['Good paraphrases change BOTH vocabulary AND sentence structure', 'Close the text before writing — paraphrase from understanding, not from the page', 'Preserve hedging and certainty levels — changing "suggests" to "proves" changes meaning'],
      },
      // # ─── Lesson 18: Understanding Irony & Understatement ───
      { id: 'b2-reading-irony', title: 'Understanding Irony & Understatement', description: 'Detect when writers mean the opposite of what they say, or deliberately minimise for effect.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Distinguish verbal irony from sarcasm', 'Recognise understatement and litotes', 'Interpret ironic and understated passages correctly'],
        sections: [
          { title: 'Types of Irony', type: 'rule', content: 'VERBAL IRONY: saying the opposite of what you mean. "What lovely weather!" (during a storm). Different from lying — the speaker EXPECTS the listener to understand the true meaning. DRAMATIC IRONY: the reader/audience knows something the character doesn\'t. In a horror film, WE see the danger but the character doesn\'t. SITUATIONAL IRONY: the outcome is the opposite of what was expected. A fire station burns down. A spelling mistake in a "Proofreading Guide." UNDERSTATEMENT (LITOTES): deliberately minimising. "It\'s a bit warm" (when it\'s 45°C). "Not bad" (meaning very good). "He\'s not the friendliest person" (meaning he\'s hostile). British English uses understatement constantly — "a spot of bother" can mean a serious crisis.' },
          { title: 'Detecting Irony in Text', type: 'tip', content: 'Without tone of voice, irony in writing is harder to spot. Clues: CONTRAST between the statement and the context. "The meeting was ONLY four hours long." ("Only" signals it felt too long.) EXAGGERATED PRAISE for something clearly bad. "A truly magnificent display of incompetence." FORMAL LANGUAGE for trivial topics (or vice versa). "The committee convened an emergency session to address the critical shortage of biscuits." JUXTAPOSITION of claim and evidence. "The diet pill promises miraculous results. Side effects include heart failure." When in doubt, ask: "Would someone GENUINELY say this? Or is the meaning inverted?" If the literal meaning seems absurd in context, it\'s probably ironic.' },
          { title: 'Detect the Irony', type: 'exercise', question: '(a) "The airline lost my luggage, cancelled my connecting flight, and charged me for an upgrade I never received. Five stars — truly an unforgettable experience." (b) "After spending £50 million on the new IT system, the government described the project as \'not entirely successful.\'" (c) "The peace conference ended in a fistfight."', answer: '(a) Verbal irony / sarcasm — "five stars" and "unforgettable" are the opposite of what the reviewer means. The listed complaints make the true opinion clear: terrible service. "Unforgettable" is darkly ironic — they won\'t forget because it was awful. (b) Understatement (litotes) — "not entirely successful" is a massive understatement for a £50 million failure. The government is minimising the disaster. The irony is between the cost (£50 million) and the tepid description ("not entirely successful"). (c) Situational irony — a PEACE conference ending in VIOLENCE is the opposite of its purpose. The irony is in the gap between intention (peace) and outcome (fighting).', answerExplanation: 'Each type requires a different reading skill: verbal irony requires you to invert the meaning, understatement requires you to amplify the meaning, and situational irony requires you to notice the contrast between expectation and reality. At B2, you should be able to detect all three — especially in British English, where understatement is the default communication mode for bad news.' },
        ],
        keyTakeaways: ['Verbal irony = saying the opposite. Understatement = deliberately minimising. Situational irony = opposite outcome.', '"Not entirely successful" in British English may mean "a complete disaster"', 'In written text, irony clues: contrast, exaggerated praise, formal language for trivial topics'],
      },
      // # ─── Lesson 19: Reading Biased Media ───
      { id: 'b2-reading-biased-media', title: 'Reading Biased Media Critically', description: 'Identify bias in news reporting and opinion writing — selection bias, framing, and loaded language.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Identify selection bias (what is included and excluded)', 'Recognise framing and loaded language', 'Read the same story from multiple outlets and compare'],
        sections: [
          { title: 'Types of Media Bias', type: 'rule', content: 'SELECTION BIAS: choosing WHICH stories to cover. A newspaper that never covers workers\' strikes has a bias — silence is also a choice. FRAMING: HOW the story is told. Same event: "Police restore order at protest" vs "Police attack peaceful demonstrators." LOADED LANGUAGE: word choice that carries judgement. "Regime" (negative) vs "government" (neutral). "Freedom fighters" vs "rebels" vs "terrorists" — same people, different framing. PLACEMENT: front page = important. Page 17 = buried. SOURCING BIAS: who gets quoted? If only government officials are quoted, the opposition\'s perspective is invisible. OMISSION: what facts are left out? An article about a company\'s growth that omits environmental violations.' },
          { title: 'Reading Across Outlets', type: 'tip', content: 'The most effective strategy against media bias: read the SAME story from 3+ outlets. Compare: WHO is quoted? (Different sources = different perspectives.) WHAT facts are included/excluded? Which outlet mentions the counter-argument? WHAT language is used? "Surge" vs "increase." "Slam" vs "criticise." WHERE is the story placed? Front page headline vs brief mention. No outlet is fully neutral. But reading across outlets reveals the PATTERN — what each one chooses to emphasise and what it hides. You don\'t need to find the "unbiased" source. You need to read ENOUGH biased sources to triangulate the truth between them.' },
          { title: 'Spot the Bias', type: 'exercise', question: 'Same event, two outlets: (A) "Heroic firefighters rescue family from devastating blaze caused by suspected arson." (B) "House fire injures four; investigation underway into possible cause." Compare the framing.', answer: '(A) LOADED LANGUAGE: "Heroic" (positive judgement of firefighters). "Devastating" (emotional amplification). "Suspected arson" (implies criminality before investigation is complete). FRAMING: focuses on drama, heroism, and crime. Makes the reader feel: admiration + outrage. (B) NEUTRAL LANGUAGE: "House fire" (factual). "Injures four" (factual). "Investigation underway" (process-focused). "Possible cause" (open — doesn\'t pre-judge). FRAMING: focuses on facts and process. Makes the reader think: I need to wait for more information. Neither is "wrong" — but (A) tells you how to feel before you have the facts, while (B) gives you the facts and lets you decide. The word "suspected" in (A) is doing significant work — it implies arson before investigation, potentially influencing public opinion.', answerExplanation: 'At B2, you recognise that BOTH outlets made choices. Outlet A chose emotional impact — "heroic," "devastating," "arson." Outlet B chose restraint — "injuries," "investigation," "possible." Neither gives you the full picture: A tells you how to feel, B might undersell the severity. The truth is probably between them. Critical media reading means recognising these choices, not just absorbing the content.' },
        ],
        keyTakeaways: ['Selection, framing, loaded language, placement, sourcing, and omission are all forms of bias', 'Read 3+ outlets on the same story — triangulate the truth between their perspectives', '"Heroic" and "devastating" tell you how to feel. "Injuries" and "investigation" let you decide.'],
      },
      // # ─── Lesson 20: Reading Reports & Executive Summaries ───
      { id: 'b2-reading-reports', title: 'Reading Reports & Executive Summaries', description: 'Navigate professional reports — extract key findings without reading every page.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Read executive summaries strategically', 'Extract key findings, recommendations, and data from reports', 'Navigate report structure without reading cover-to-cover'],
        sections: [
          { title: 'Report Structure', type: 'rule', content: 'Professional reports follow a standard structure: EXECUTIVE SUMMARY (1-2 pages): the entire report condensed. Read this FIRST — it gives you: the purpose, key findings, and recommendations. TABLE OF CONTENTS: your navigation map. Scan it to understand the report\'s scope. INTRODUCTION: background, context, why the report was written. METHODOLOGY: how data was collected. Important for evaluating reliability. FINDINGS: the data and analysis. Usually the longest section. CONCLUSIONS: what the findings mean. RECOMMENDATIONS: what should be done. APPENDICES: supporting data, full datasets, technical details. Strategy: read the executive summary → scan recommendations → read only the sections relevant to YOUR question. You rarely need to read a 100-page report cover to cover.' },
          { title: 'Extracting Key Information', type: 'tip', content: 'When reading a report, ask: PURPOSE: why was this report written? Who commissioned it? SCOPE: what does it cover and what doesn\'t it cover? KEY FINDINGS: what are the 3-5 main discoveries? EVIDENCE QUALITY: how was the data collected? Sample size? Time period? RECOMMENDATIONS: what actions are proposed? Who should act? LIMITATIONS: what does the report admit it cannot prove? Most reports have a "Limitations" section — this is often the most honest part. It tells you what the report CANNOT claim, which is as valuable as what it can. If a report has no limitations section, be sceptical — every study has limitations.' },
          { title: 'Extract the Essentials', type: 'exercise', question: 'Executive Summary extract: "This report examines employee wellbeing across 12 organisations in the UK financial sector (n=4,200). Key findings: 67% of employees report moderate to high stress levels; stress correlates with overtime hours (r=0.58); flexible working policies reduce reported stress by 23%. Recommendations: implement flexible working options, limit mandatory overtime to 5 hours per week, and provide mental health support. Limitations: self-reported data; financial sector only; cross-sectional design (no causation)."', answer: 'Extracted: PURPOSE: examine employee wellbeing in UK finance. SCOPE: 12 organisations, 4,200 employees, financial sector only. KEY FINDINGS: (1) 67% report moderate-high stress. (2) Stress correlates with overtime (r=0.58, moderate-strong). (3) Flexible working reduces stress by 23%. RECOMMENDATIONS: (1) Flexible working. (2) Cap overtime at 5 hrs/week. (3) Mental health support. LIMITATIONS: (1) Self-reported (people may over/understate). (2) Finance only (may not apply to other sectors). (3) Cross-sectional (shows correlation, not causation — overtime may not CAUSE stress, stress may cause overtime). CRITICAL NOTE: "reduces stress by 23%" is correlational, not causal (per limitations). The recommendation to "implement flexible working" goes beyond what the data proves.', answerExplanation: 'The most important skill is connecting the LIMITATIONS to the FINDINGS. The report says flexible working "reduces stress by 23%" — but the limitations say "cross-sectional design, no causation." This means the report cannot prove that flexible working CAUSES the reduction. The recommendation is plausible but not proven by this study. Reading the limitations section changes how you interpret everything else.' },
        ],
        keyTakeaways: ['Read executive summaries FIRST — they condense the whole report', 'Always read the Limitations section — it tells you what the report CANNOT prove', 'Connect limitations to findings — "reduces by 23%" + "no causation" = correlation only'],
      },
      // # ─── Lesson 21: Active Reading & Annotation ───
      { id: 'b2-reading-annotation', title: 'Active Reading & Annotation Strategies', description: 'Transform passive reading into active learning through annotation, questioning, and note-taking.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Use annotation to improve comprehension and retention', 'Apply the Cornell note-taking method to reading', 'Develop a personal reading system'],
        sections: [
          { title: 'Why Annotate?', type: 'rule', content: 'Reading without annotating is like listening without thinking. Active reading strategies: HIGHLIGHT key claims (not everything — maximum 10-15% of the text). UNDERLINE vocabulary you want to learn. MARGIN NOTES: write brief reactions. "Disagree!" "Need evidence." "Good example." "Compare to Chapter 2." QUESTION MARKS: mark passages you don\'t understand. Return to them. ARROWS: connect related ideas across paragraphs. STAR / ASTERISK: mark the most important points. SUMMARY: at the end of each section, write a 1-sentence summary in your own words. Research shows that annotating increases retention by 20-30% compared to passive reading. The act of writing forces your brain to process the information more deeply.' },
          { title: 'Cornell Notes for Reading', type: 'tip', content: 'Divide your page into three sections: LEFT COLUMN (narrow): questions or keywords. RIGHT COLUMN (wide): notes, summaries, key points from the reading. BOTTOM SECTION: a 2-3 sentence summary of the whole text. While reading, take notes in the RIGHT column. After reading, write questions in the LEFT column that your notes answer. Cover the right column and test yourself using only the questions. This method is powerful because it turns reading into: (1) note-taking (active processing), (2) question-generation (deeper processing), and (3) self-testing (retrieval practice). All three are proven to improve learning and retention.' },
          { title: 'Annotate This Passage', type: 'exercise', question: 'Read and annotate: "The gig economy has grown rapidly, offering flexibility to workers. However, gig workers lack traditional benefits such as healthcare, pensions, and paid leave. Companies argue that workers prefer independence, but surveys consistently show that most gig workers would choose traditional employment if it were available. The legal status of gig workers remains contested in most countries." What would you highlight, question, and summarise?', answer: 'Annotations: HIGHLIGHT: "gig workers lack traditional benefits" (key problem). HIGHLIGHT: "most gig workers would choose traditional employment" (challenges company narrative). QUESTION: "What surveys? Sample size? Which countries?" (claims need evidence). MARGIN NOTE at "Companies argue": "Who benefits from this framing? The companies." MARGIN NOTE at "flexibility": "Flexibility FOR workers or FOR companies?" STAR: "legal status remains contested" — this is the unresolved core issue. CONNECTION: "lack benefits" ↔ "legal status contested" — these are linked (if classified as employees, they would get benefits). SUMMARY: The gig economy offers flexibility but denies workers key benefits; companies claim workers prefer independence, but evidence suggests otherwise, and the legal debate remains unresolved.', answerExplanation: 'Active annotation transforms this paragraph from something you READ into something you ANALYSED. The questions ("What surveys?") push you to evaluate evidence. The margin notes ("Who benefits?") push you to think critically. The connection (benefits ↔ legal status) reveals the underlying structure. And the summary forces you to synthesise. This is the difference between reading and studying — and it applies to any text in any language.' },
        ],
        keyTakeaways: ['Annotating increases retention by 20-30% — highlight, question, connect, summarise', 'Cornell method: notes (right), questions (left), summary (bottom), then self-test', 'Limit highlighting to 10-15% — if everything is highlighted, nothing stands out'],
      },
      // # ─── Lesson 22: Deducing Vocabulary from Context ───
      { id: 'b2-reading-vocab-context', title: 'Deducing Vocabulary from Context', description: 'Figure out unknown word meanings from surrounding text — without a dictionary.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Use context clues to guess word meanings', 'Identify definition, contrast, and example context clues', 'Build vocabulary through strategic reading'],
        sections: [
          { title: 'Types of Context Clues', type: 'rule', content: 'When you meet an unknown word, the surrounding text often tells you: DEFINITION: the word is defined directly. "Photosynthesis — the process by which plants convert sunlight into energy — is essential for life." SYNONYM / RESTATEMENT: a similar word nearby. "The treatment was efficacious; in other words, it worked." CONTRAST / ANTONYM: the opposite is given. "Unlike her gregarious sister, Emma was quiet and preferred to be alone." (Gregarious = sociable.) EXAMPLE: examples clarify the meaning. "Legumes, such as lentils, chickpeas, and beans, are high in protein." GENERAL CONTEXT: the overall meaning of the passage suggests the word\'s meaning. "The jury\'s verdict was unanimous — all twelve members agreed." (Unanimous = everyone agrees.)' },
          { title: 'The 5-Step Guess', type: 'tip', content: 'When you find an unknown word: (1) Read the WHOLE sentence (not just the word). (2) Check for definition clues (dashes, "that is," "in other words"). (3) Check for contrast clues ("unlike," "however," "but"). (4) Determine the word\'s PART OF SPEECH (noun/verb/adjective?). (5) Make your best guess, then read the sentence with your guess substituted. Does it make sense? Example: "The government\'s parsimonious approach to healthcare funding has left hospitals struggling." Step 1: whole sentence = government spending too little. Step 4: adjective (describes "approach"). Step 5: guess = stingy/tight/cheap. Substitute: "The government\'s stingy approach..." — yes, makes sense. (Parsimonious = extremely unwilling to spend money.)' },
          { title: 'Guess the Meaning', type: 'exercise', question: '(a) "The speaker\'s rhetoric was so compelling that even her opponents found themselves nodding in agreement." (b) "The once-pristine beach was now littered with rubbish, its beauty obliterated by years of neglect." (c) "His phlegmatic response to the crisis surprised everyone — while others panicked, he remained calm and unhurried."', answer: '(a) "Compelling" = powerfully convincing/persuasive. Context clue: even OPPONENTS were nodding — so the rhetoric was strong enough to convince people who disagreed. (b) "Obliterated" = completely destroyed/removed. Context clue: contrast between "once-pristine" (past beauty) and "littered with rubbish" (current state). "Obliterated" describes the complete loss. (c) "Phlegmatic" = calm, unemotional, not easily excited. Context clue: direct definition — "while others panicked, he remained calm and unhurried." The sentence after the dash explains the word.', answerExplanation: 'You didn\'t need a dictionary for any of these. Context clues gave you enough: (a) effect on opponents → powerful/convincing. (b) contrast with "pristine" → destroyed. (c) explicit restatement → calm. At B2, you encounter 3-5 unknown words per page of academic text. Using context clues lets you keep reading without stopping — and research shows that words learned from context are retained LONGER than words looked up in a dictionary, because the surrounding context creates memory anchors.' },
        ],
        keyTakeaways: ['Definition, synonym, contrast, example, and general context all provide word-meaning clues', 'Determine part of speech first, guess the meaning, then substitute your guess to check', 'Words learned from context are retained longer than dictionary lookups'],
      },
      // # ─── Lesson 23: Reading for Exam Success ───
      { id: 'b2-reading-exam-strategies', title: 'Reading for Exam Success', description: 'Master exam-specific reading strategies for IELTS, Cambridge, and other English proficiency tests.',
        skill: 'reading', level: 'B2', duration: 14,
        objectives: ['Apply time management strategies for timed reading tests', 'Handle common exam question types: matching, True/False/Not Given, multiple choice', 'Avoid common exam reading traps'],
        sections: [
          { title: 'Exam Reading Strategy', type: 'rule', content: 'Exams test SPECIFIC reading skills under TIME PRESSURE: TIME MANAGEMENT: IELTS Reading = 60 minutes, 40 questions, 3 passages. Spend ~20 minutes per passage. If stuck on a question for >2 minutes, MOVE ON and return later. READ QUESTIONS FIRST: know what you\'re looking for BEFORE reading the passage. This transforms passive reading into active searching. SKIM → SCAN → READ: (1) Skim the passage in 2-3 minutes (headings, first sentences, conclusion). (2) Scan for keywords from the questions. (3) Read carefully ONLY the relevant paragraphs. DON\'T READ EVERY WORD: exam passages are 700-900 words. You don\'t have time to read every word three times. Target your reading.' },
          { title: 'Common Exam Traps', type: 'tip', content: 'TRUE/FALSE/NOT GIVEN is the hardest question type: TRUE = the passage says this. FALSE = the passage says the OPPOSITE. NOT GIVEN = the passage doesn\'t mention this at all. Common trap: confusing FALSE with NOT GIVEN. "The study included 500 participants" — if the passage says "200 participants," the answer is FALSE. If the passage doesn\'t mention participant numbers at all, the answer is NOT GIVEN. MATCHING HEADINGS: read the FIRST and LAST sentence of each paragraph — the heading usually matches one of these. MULTIPLE CHOICE: eliminate obviously wrong answers first. Often two answers are clearly wrong and two are close — focus your analysis on the close pair. SENTENCE COMPLETION: the answer must be grammatically correct AND factually accurate from the passage.' },
          { title: 'Practice: True, False, or Not Given?', type: 'exercise', question: 'Passage: "The university was founded in 1850 and currently has approximately 15,000 students. It offers courses in 42 subjects across six faculties. International students make up 30% of the student body." Statements: (a) The university was established in the 19th century. (b) The university has more than 20,000 students. (c) The university is considered one of the best in the country.', answer: '(a) TRUE — 1850 is in the 19th century. The passage confirms this. (b) FALSE — the passage says "approximately 15,000" which is NOT more than 20,000. This directly contradicts the statement. (c) NOT GIVEN — the passage mentions facts about the university but never discusses its ranking or quality. The trap: (c) SEEMS reasonable — a university with 15,000 students and 42 subjects MIGHT be highly ranked — but the passage doesn\'t SAY this. NOT GIVEN means the information simply isn\'t there, regardless of what seems likely.', answerExplanation: 'The key distinction: FALSE = the passage contradicts the statement. NOT GIVEN = the passage doesn\'t address the topic at all. Students lose marks by writing FALSE when the answer is NOT GIVEN, because they feel "the passage would probably disagree." But T/F/NG questions test what the passage SAYS, not what it might imply. If it\'s not stated, it\'s NOT GIVEN — no matter how reasonable the inference seems.' },
        ],
        keyTakeaways: ['Read QUESTIONS first, then skim/scan the passage — don\'t read every word', 'TRUE = confirmed. FALSE = contradicted. NOT GIVEN = not mentioned at all.', 'If stuck for >2 minutes, mark your best guess, move on, and return later'],
      },
      // # ─── Lesson 24: Reading Autobiography & Memoir ───
      { id: 'b2-reading-memoir', title: 'Reading Autobiography & Memoir', description: 'Engage with personal narratives — understanding how real experiences are shaped into stories.',
        skill: 'reading', level: 'B2', duration: 10,
        objectives: ['Understand the difference between autobiography, memoir, and biography', 'Recognise how writers select and shape personal experiences', 'Read personal narratives critically while empathetically'],
        sections: [
          { title: 'Types of Life Writing', type: 'rule', content: 'AUTOBIOGRAPHY: a person\'s FULL life story, written by themselves. Chronological, comprehensive. "I was born in..." through to the present. MEMOIR: a FOCUSED account of a specific period, theme, or experience. Not the whole life — a slice of it. "My year teaching in rural Japan." "Growing up bilingual." BIOGRAPHY: someone ELSE writes about the person. Uses research, interviews, and archives. Key understanding: all three are CONSTRUCTED. Even autobiography is selective — you cannot include everything. The writer CHOOSES what to include and exclude, how to sequence events, and which moments to emphasise. A memoir about childhood emphasises different events than a memoir about career. Memory itself is reconstructive, not a recording — so all life writing involves interpretation.' },
          { title: 'Reading Memoir Critically', type: 'tip', content: 'Memoirs feel TRUE because they use real names and events. But consider: SELECTIVE MEMORY: the writer includes events that support their narrative and omits those that don\'t. NARRATIVE ARC: real life doesn\'t have a beginning, middle, and end — the writer imposes structure. DIALOGUE: conversations from 20 years ago are reconstructed, not transcribed. They are "true in spirit" but not literal. PERSPECTIVE: the writer is both the protagonist and the narrator. They control how every other person in the story is portrayed. HINDSIGHT: the writer knows how things turned out. This knowledge shapes how they describe events that, at the time, were uncertain. Read memoirs for EMOTIONAL truth (what it felt like) rather than FACTUAL truth (exactly what happened). The two are different, and memoir excels at the former.' },
          { title: 'Evaluate This Memoir Extract', type: 'exercise', question: '"I remember the exact moment everything changed. I was sitting in my grandmother\'s kitchen, the radio crackling in the corner, when she looked at me and said, \'You\'re going to be something special, mark my words.\' I was seven years old. I carried those words with me for the next thirty years."', answer: 'Reading critically: (1) "I remember the exact moment" — this is probably reconstructed. Memory research shows we don\'t remember moments "exactly" — we reconstruct them each time we recall them. (2) The dialogue ("You\'re going to be something special") — said 30+ years ago. The words may not be exact. But they represent what the writer FELT the grandmother communicated. (3) "I carried those words for thirty years" — this is hindsight. At seven, the writer didn\'t know these words would be significant. Looking back, they assign importance to this moment because of what happened later. (4) The scene is vivid ("crackling radio," "grandmother\'s kitchen") — these sensory details make it feel true, but they may be imagined or borrowed from other memories. EMOTIONAL truth: the grandmother\'s belief in the writer was formative. This is probably genuinely true — even if the exact words and setting are reconstructed.', answerExplanation: 'This passage demonstrates how memoir works: a specific moment is selected, vivid details are added (or remembered), dialogue is reconstructed, and hindsight gives the moment significance it may not have had at the time. This doesn\'t make the memoir dishonest — it makes it human. All memory works this way. Reading memoir critically means understanding this construction while still engaging with the emotional truth it communicates.' },
        ],
        keyTakeaways: ['Autobiography = full life. Memoir = one slice. Biography = someone else writes it.', 'Dialogue from decades ago is reconstructed, not transcribed — read for emotional truth, not literal accuracy', 'Hindsight shapes memoir — the writer knows the ending, which changes how they describe the beginning'],
      },
      // # ─── Lesson 25: B2 Reading Review ───
      { id: 'b2-reading-review', title: 'B2 Reading Review: Advanced Skills Consolidation', description: 'Review all B2 reading skills and prepare for C1-level complexity.',
        skill: 'reading', level: 'B2', duration: 12,
        objectives: ['Apply all B2 reading strategies to complex texts', 'Self-assess advanced reading skills', 'Identify areas for C1 development'],
        sections: [
          { title: 'Your B2 Reading Skills', type: 'rule', content: 'At B2, you can now: ✓ Follow complex arguments with concessions and rebuttals. ✓ Evaluate source reliability using the CRAAP test. ✓ Make advanced inferences from subtext, juxtaposition, and omission. ✓ Navigate academic research papers strategically. ✓ Read literary fiction for symbolism and theme. ✓ Track discourse markers and synonym chains for cohesion. ✓ Speed read when appropriate using chunking and pointers. ✓ Synthesise multiple sources into coherent understanding. ✓ Analyse rhetoric (ethos, pathos, logos). ✓ Read across cultures with awareness of indirect communication. ✓ Read satire, long-form journalism, and literary criticism. These skills make you a confident, critical reader in English.' },
          { title: 'B2 → C1 Bridge', type: 'tip', content: 'What changes at C1: texts become longer and more abstract. Arguments have more layers and more subtle hedging. Academic texts assume prior knowledge of the field. Literary analysis goes deeper — narrative technique, voice, ideology. You will read texts that deliberately challenge your views. You will evaluate not just WHAT an argument says but HOW it constructs knowledge. C1 reading is less about comprehension and more about critical evaluation — not "What does this mean?" but "Why does the writer want me to think this?" and "What alternative interpretations exist?"' },
          { title: 'Comprehensive B2 Exercise', type: 'exercise', question: '"A controversial new study claims that remote workers are 23% more productive than office workers. The research, funded by a major remote-work platform, surveyed 2,000 of the platform\'s own users. \'Our findings challenge the traditional office model,\' said CEO Sarah Lin. However, workplace psychologist Dr James Okonkwo cautioned: \'Self-reported productivity from a self-selected sample tells us very little. We need randomised controlled trials.\'" Evaluate the reliability and identify the rhetorical strategies.', answer: 'Reliability concerns: (1) Funded by a remote-work platform — financial conflict of interest (they profit from positive remote work data). (2) Surveyed their own users — sampling bias (people who chose remote work are likely to praise it). (3) Self-reported productivity — not objectively measured. (4) "Self-selected sample" (Dr Okonkwo) — participants chose to be there, not randomly assigned. Rhetoric: CEO uses ETHOS ("our findings") and LOGOS (23% statistic). Dr Okonkwo uses LOGOS (methodological critique) and ETHOS (workplace psychologist credentials). The journalist\'s framing: "controversial" and "claims" (not "proves") signal scepticism. Placing Dr Okonkwo\'s rebuttal last gives it the final word — a structural choice that favours the critical perspective. Overall: the study is unreliable. Interesting as a data point but not evidence for policy decisions.', answerExplanation: 'This exercise tests source evaluation (CRAAP — funding, methodology), rhetorical analysis (ethos/logos from both sides), inference (the journalist\'s word choices signal doubt), and critical thinking (why self-selection and self-reporting matter). At B2, you don\'t just READ this article — you EVALUATE it. That is the fundamental shift from intermediate to advanced reading.' },
        ],
        keyTakeaways: ['B2 reading = evaluation, not just comprehension. "What does the writer want me to think?"', 'Always check: funding source, sample selection, measurement method, and conflict of interest', 'C1 goes further: "Why does this text construct knowledge THIS way? What alternatives exist?"'],
      },
    ],
  },
]
